```turtle
@prefix fis:  <http://example.org/onto/securities#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .

<http://example.org/onto/securities>
    a owl:Ontology ;
    rdfs:comment "An ontology of securities, financial instruments and derivatives, modelled from a corpus on securities law and finance." .

#################################################################
#  OBJECT PROPERTIES
#################################################################

fis:hasIssuer a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain fis:FinancialInstrument ;
    rdfs:range  fis:Issuer ;
    rdfs:label "has issuer" ;
    rdfs:comment "The entity issuing the security is called the issuer." .

fis:isIssuerOf a owl:ObjectProperty ;
    owl:inverseOf fis:hasIssuer ;
    rdfs:domain fis:Issuer ;
    rdfs:range  fis:FinancialInstrument .

fis:hasUnderlying a owl:ObjectProperty ;
    rdfs:domain fis:FinancialInstrument ;
    rdfs:range  fis:Asset ;
    rdfs:label "has underlying" ;
    rdfs:comment "The underlier: an asset (commodity, financial instrument, index, currency, interest rate) on which a derivative or asset-backed security is based." .

fis:isUnderlyingOf a owl:ObjectProperty ;
    owl:inverseOf fis:hasUnderlying ;
    rdfs:domain fis:Asset ;
    rdfs:range  fis:FinancialInstrument .

fis:hasHolder a owl:ObjectProperty ;
    rdfs:domain fis:Security ;
    rdfs:range  fis:Investor ;
    rdfs:label "has holder" .

fis:isHolderOf a owl:ObjectProperty ;
    owl:inverseOf fis:hasHolder ;
    rdfs:domain fis:Investor ;
    rdfs:range  fis:Security .

fis:hasReferenceEntity a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain fis:CreditDefaultSwap ;
    rdfs:range  fis:Issuer ;
    rdfs:comment "The debt issuer whose creditworthiness backs a credit default swap." .

fis:isReferenceEntityOf a owl:ObjectProperty ;
    owl:inverseOf fis:hasReferenceEntity ;
    rdfs:domain fis:Issuer ;
    rdfs:range  fis:CreditDefaultSwap .

fis:hasDividend a owl:ObjectProperty ;
    rdfs:domain fis:EquitySecurity ;
    rdfs:range  fis:Dividend .

fis:isDividendOf a owl:ObjectProperty ;
    owl:inverseOf fis:hasDividend ;
    rdfs:domain fis:Dividend ;
    rdfs:range  fis:EquitySecurity .

#################################################################
#  DATATYPE PROPERTIES
#################################################################

fis:hasMaturityDate a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:FinancialInstrument ;
    rdfs:range xsd:date ;
    rdfs:comment "The date on which principal is repaid / the contract expires. Perpetual instruments have no value for this property." .

fis:hasFaceValue a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:DebtSecurity ;
    rdfs:range xsd:decimal ;
    rdfs:label "has face value" ;
    rdfs:comment "Nominal, principal, par or face amount; fixed for the life of the instrument." .

fis:hasCouponRate a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Bond ;
    rdfs:range xsd:decimal .

fis:hasCouponType a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Bond ;
    rdfs:range xsd:string ;
    rdfs:comment "One of: fixed, floating, zero." .

fis:hasStrikePrice a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Option ;
    rdfs:range xsd:decimal ;
    rdfs:comment "Fixed at issuance of the option contract and does not change during its life." .

fis:hasCreditRating a owl:DatatypeProperty ;
    rdfs:domain fis:Bond ;
    rdfs:range xsd:string .

fis:hasCreditRatingCategory a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Bond ;
    rdfs:range xsd:string ;
    rdfs:comment "One of: investment-grade, high-yield." .

fis:isCallable a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Bond ;
    rdfs:range xsd:boolean .

fis:isPutable a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Bond ;
    rdfs:range xsd:boolean .

fis:isConvertible a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Security ;
    rdfs:range xsd:boolean .

fis:hasSeniorityRank a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Bond ;
    rdfs:range xsd:string ;
    rdfs:comment "One of: senior, subordinated." .

fis:hasTermLength a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Security ;
    rdfs:range xsd:string ;
    rdfs:comment "One of: short, medium, long, perpetual, dated." .

fis:hasCumulativeDividend a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:PreferredStock ;
    rdfs:range xsd:boolean .

fis:hasRightToBuy a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Option ;
    rdfs:range xsd:boolean ;
    rdfs:comment "True if the option conveys a right to buy (call), false if a right to sell (put)." .

fis:hasExerciseStyle a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Option ;
    rdfs:range xsd:string ;
    rdfs:comment "One of: American, European, Bermudan." .

fis:isStandardized a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Derivative ;
    rdfs:range xsd:boolean .

fis:isExchangeTraded a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Derivative ;
    rdfs:range xsd:boolean .

fis:hasObligationToPerform a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Derivative ;
    rdfs:range xsd:boolean ;
    rdfs:comment "True for lock products (forwards, futures, swaps); false for option products." .

fis:hasPrincipalInvestmentType a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:MutualFund ;
    rdfs:range xsd:string ;
    rdfs:comment "One of: money-market, bond, equity, hybrid." .

#################################################################
#  TOP-LEVEL CLASSES
#################################################################

fis:Asset a owl:Class ;
    rdfs:label "asset" .

fis:FinancialInstrument a owl:Class ;
    rdfs:subClassOf fis:Asset ;
    rdfs:comment "A monetary contract between parties; can be created, traded, modified and settled." .

fis:Commodity a owl:Class ; rdfs:subClassOf fis:Asset .
fis:Currency a owl:Class ; rdfs:subClassOf fis:Asset .
fis:PriceIndex a owl:Class ; rdfs:subClassOf fis:Asset .
fis:InterestRateIndex a owl:Class ; rdfs:subClassOf fis:Asset .

fis:CashInstrument a owl:Class ;
    rdfs:subClassOf fis:FinancialInstrument ;
    rdfs:comment "An instrument whose value is determined directly by the markets (securities, loans, deposits)." .

fis:Derivative a owl:Class ;
    rdfs:subClassOf fis:FinancialInstrument ;
    rdfs:comment "A contract deriving its value from the value and characteristics of one or more underlying entities. NOTE: the US legal definition classifies derivatives as a type of security, conflicting with the cash/derivative-instrument split used elsewhere in the corpus; this ontology follows the latter, more general, framing and treats Derivative as a sibling of CashInstrument." .

owl:AllDisjointClasses [ owl:members ( fis:CashInstrument fis:Derivative ) ] .

fis:HybridSecurity a owl:Class ;
    rdfs:subClassOf fis:FinancialInstrument ;
    rdfs:comment "Combines characteristics of both debt and equity securities (and, in the case of warrants, of derivatives). Deliberately not placed under CashInstrument or Derivative, and not asserted disjoint with either, because members such as ConvertibleBond and EquityWarrant also belong to those branches." .

#################################################################
#  SECURITY
#################################################################

fis:Security a owl:Class ;
    rdfs:subClassOf fis:CashInstrument ;
    rdfs:comment "A tradable financial asset." .

fis:DebtSecurity a owl:Class ; rdfs:subClassOf fis:Security .
fis:EquitySecurity a owl:Class ; rdfs:subClassOf fis:Security .

owl:AllDisjointClasses [ owl:members ( fis:DebtSecurity fis:EquitySecurity ) ] .

fis:Loan a owl:Class ; rdfs:subClassOf fis:CashInstrument .
fis:Deposit a owl:Class ; rdfs:subClassOf fis:CashInstrument .

fis:RepurchaseAgreement a owl:Class ;
    rdfs:subClassOf fis:CashInstrument ;
    rdfs:comment "Defies categorisation into the cash/derivative matrix." .

fis:Mortgage a owl:Class ; rdfs:subClassOf fis:Loan .
fis:ResidentialMortgage a owl:Class ; rdfs:subClassOf fis:Mortgage .
fis:CommercialMortgage a owl:Class ; rdfs:subClassOf fis:Mortgage .
owl:AllDisjointClasses [ owl:members ( fis:ResidentialMortgage fis:CommercialMortgage ) ] .

fis:ConsumerLoan a owl:Class ; rdfs:subClassOf fis:Loan .
fis:AutoLoan a owl:Class ; rdfs:subClassOf fis:ConsumerLoan .
fis:StudentLoan a owl:Class ; rdfs:subClassOf fis:ConsumerLoan .
fis:CreditCardReceivable a owl:Class ; rdfs:subClassOf fis:ConsumerLoan .
fis:HomeEquityLoan a owl:Class ; rdfs:subClassOf fis:ConsumerLoan , fis:ResidentialMortgage .
owl:AllDisjointClasses [ owl:members ( fis:AutoLoan fis:StudentLoan fis:CreditCardReceivable fis:HomeEquityLoan ) ] .

fis:CertificateOfDeposit a owl:Class ;
    rdfs:subClassOf fis:Deposit ;
    rdfs:comment "A time deposit; negotiable ('jumbo') CDs also function as money market instruments." .

#################################################################
#  SECURITY FORM / NATURE DIMENSIONS
#################################################################

fis:CertificatedSecurity a owl:Class ; rdfs:subClassOf fis:Security .
fis:NonCertificatedSecurity a owl:Class ; rdfs:subClassOf fis:Security .
owl:AllDisjointClasses [ owl:members ( fis:CertificatedSecurity fis:NonCertificatedSecurity ) ] .

fis:BearerSecurity a owl:Class ;
    rdfs:subClassOf fis:CertificatedSecurity ;
    rdfs:comment "Entitles the holder to rights merely by holding the security." .
fis:RegisteredSecurity a owl:Class ;
    rdfs:subClassOf fis:CertificatedSecurity ;
    rdfs:comment "Entitles the holder to rights only if registered on a security register." .
owl:AllDisjointClasses [ owl:members ( fis:BearerSecurity fis:RegisteredSecurity ) ] .

fis:DividedSecurity a owl:Class ;
    rdfs:subClassOf fis:Security ;
    rdfs:comment "Each instrument constitutes a separate, legally distinct asset/debt." .
fis:UndividedSecurity a owl:Class ;
    rdfs:subClassOf fis:Security ;
    rdfs:comment "The entire issue is one single asset; each security is a fractional part." .
owl:AllDisjointClasses [ owl:members ( fis:DividedSecurity fis:UndividedSecurity ) ] .

fis:FungibleSecurity a owl:Class ;
    rdfs:subClassOf fis:Security ;
    rdfs:comment "All holdings are treated identically and are interchangeable." .
fis:NonFungibleSecurity a owl:Class ; rdfs:subClassOf fis:Security .
owl:AllDisjointClasses [ owl:members ( fis:FungibleSecurity fis:NonFungibleSecurity ) ] .

#################################################################
#  ISSUER / INVESTOR
#################################################################

fis:Issuer a owl:Class ; rdfs:comment "The company or other entity issuing a security." .
fis:SovereignGovernment a owl:Class ; rdfs:subClassOf fis:Issuer .
fis:MunicipalGovernment a owl:Class ; rdfs:subClassOf fis:Issuer .
fis:SupranationalOrganization a owl:Class ; rdfs:subClassOf fis:Issuer .
fis:Corporation a owl:Class ; rdfs:subClassOf fis:Issuer .
owl:AllDisjointClasses [ owl:members ( fis:SovereignGovernment fis:MunicipalGovernment fis:SupranationalOrganization fis:Corporation ) ] .

fis:Investor a owl:Class .
fis:Shareholder a owl:Class ;
    rdfs:subClassOf fis:Investor ;
    rdfs:comment "An individual or company that legally owns one or more shares of stock." .
fis:Bondholder a owl:Class ;
    rdfs:subClassOf fis:Investor ;
    rdfs:comment "The creditor to whom the bond issuer owes principal and interest." .

fis:Dividend a owl:Class .
fis:CashDividend a owl:Class ; rdfs:subClassOf fis:Dividend .
fis:StockDividend a owl:Class ; rdfs:subClassOf fis:Dividend .
owl:AllDisjointClasses [ owl:members ( fis:CashDividend fis:StockDividend ) ] .

#################################################################
#  BOND
#################################################################

fis:Bond a owl:Class ;
    rdfs:subClassOf fis:DebtSecurity ;
    rdfs:comment "The issuer owes the holder a debt and is obliged to repay principal at maturity plus, usually, interest (the coupon)." .

### by issuer
fis:GovernmentBond a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SovereignGovernment ] ) ] ;
    rdfs:label "treasury bond" , "sovereign bond" .

fis:MunicipalBond a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:MunicipalGovernment ] ) ] ;
    rdfs:label "muni" .

fis:SupranationalBond a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SupranationalOrganization ] ) ] ;
    rdfs:label "supra" .

fis:CorporateBond a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Corporation ] ) ] .

owl:AllDisjointClasses [ owl:members ( fis:GovernmentBond fis:MunicipalBond fis:SupranationalBond fis:CorporateBond ) ] .

fis:WarBond a owl:Class ; rdfs:subClassOf fis:GovernmentBond ;
    rdfs:comment "Issued to fund military operations during wartime." .

fis:GeneralObligationBond a owl:Class ; rdfs:subClassOf fis:MunicipalBond ;
    rdfs:comment "Secured by the full faith and credit and taxing power of the issuer." .
fis:AssessmentBond a owl:Class ; rdfs:subClassOf fis:GeneralObligationBond ;
    rdfs:comment "Repayment based on property tax assessments; government still obligated if assessments fail." .
fis:RevenueBond a owl:Class ; rdfs:subClassOf fis:MunicipalBond ;
    rdfs:comment "Guarantee of repayment solely from revenues of a specified revenue-generating entity; typically non-recourse." .
fis:BuildAmericaBond a owl:Class ; rdfs:subClassOf fis:MunicipalBond ;
    rdfs:comment "Taxable municipal bond authorised by the American Recovery and Reinvestment Act of 2009." .

fis:Gilt a owl:Class ; rdfs:subClassOf fis:GovernmentBond ;
    rdfs:comment "UK government bond." .
fis:ConventionalGilt a owl:Class ; rdfs:subClassOf fis:Gilt .
fis:IndexLinkedGilt a owl:Class ; rdfs:subClassOf fis:Gilt .
owl:AllDisjointClasses [ owl:members ( fis:ConventionalGilt fis:IndexLinkedGilt ) ] .

fis:TreasurySecurity a owl:Class ; rdfs:subClassOf fis:GovernmentBond ;
    rdfs:comment "US government debt issued by the US Department of the Treasury." .
fis:TreasuryBill a owl:Class ; rdfs:subClassOf fis:TreasurySecurity ;
    rdfs:comment "Zero-coupon bond maturing in one year or less." .
fis:TreasuryNote a owl:Class ; rdfs:subClassOf fis:TreasurySecurity ;
    rdfs:comment "Maturity of two, three, five or ten years." .
fis:TreasuryBond a owl:Class ; rdfs:subClassOf fis:TreasurySecurity ;
    rdfs:comment "Longest maturity, twenty to thirty years." .
fis:TreasuryInflationProtectedSecurity a owl:Class ; rdfs:subClassOf fis:TreasurySecurity .
fis:TreasuryFloatingRateNote a owl:Class ; rdfs:subClassOf fis:TreasurySecurity .
owl:AllDisjointClasses [ owl:members ( fis:TreasuryBill fis:TreasuryNote fis:TreasuryBond fis:TreasuryInflationProtectedSecurity fis:TreasuryFloatingRateNote ) ] .

### Asset-backed family (bonds backed by cash flows from other assets)
fis:AssetBackedSecurity a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:comment "Bonds whose interest and principal payments are backed by underlying cash flows from other assets. NOTE: the corpus also uses 'asset-backed security' narrowly to mean only consumer-loan-backed securities, excluding MBS and CDO; this narrower sense is modelled as fis:ConsumerAssetBackedSecurity." .

fis:MortgageBackedSecurity a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:AssetBackedSecurity
        [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:Mortgage ] ) ] .

fis:CollateralizedDebtObligation a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:AssetBackedSecurity
        [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:DebtSecurity ] ) ] ;
    rdfs:comment "Originally corporate-debt markets, later encompassing mortgage/MBS markets; often composed of recycled ABS tranches." .

fis:CoveredBond a owl:Class ; rdfs:subClassOf fis:Bond ;
    rdfs:disjointWith fis:AssetBackedSecurity ;
    rdfs:comment "Backed by cash flows from mortgages or public sector assets which remain on the issuer's balance sheet (unlike ABS)." .

fis:PassThroughSecurity a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity ;
    rdfs:comment "The basic MBS: interest and principal pass through to holders pro rata." .
fis:CollateralizedMortgageObligation a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity ;
    rdfs:comment "'Pay-through bond': divided into tranches with differing maturities/priorities." .
fis:StrippedMortgageBackedSecurity a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity .
owl:AllDisjointClasses [ owl:members ( fis:PassThroughSecurity fis:CollateralizedMortgageObligation fis:StrippedMortgageBackedSecurity ) ] .

fis:ResidentialMortgageBackedSecurity a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:PassThroughSecurity
        [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:ResidentialMortgage ] ) ] .
fis:CommercialMortgageBackedSecurity a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:PassThroughSecurity
        [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:CommercialMortgage ] ) ] .
owl:AllDisjointClasses [ owl:members ( fis:ResidentialMortgageBackedSecurity fis:CommercialMortgageBackedSecurity ) ] .

fis:InterestOnlyStrip a owl:Class ; rdfs:subClassOf fis:StrippedMortgageBackedSecurity ;
    rdfs:comment "Cash flows backed by the interest component of mortgage payments." .
fis:PrincipalOnlyStrip a owl:Class ; rdfs:subClassOf fis:StrippedMortgageBackedSecurity ;
    rdfs:comment "Cash flows backed by the principal-repayment component of mortgage payments." .
owl:AllDisjointClasses [ owl:members ( fis:InterestOnlyStrip fis:PrincipalOnlyStrip ) ] .
fis:NetInterestMarginSecurity a owl:Class ; rdfs:subClassOf fis:StrippedMortgageBackedSecurity ;
    rdfs:comment "Re-securitised residual interest of an MBS." .

fis:ConsumerAssetBackedSecurity a owl:Class ; rdfs:subClassOf fis:AssetBackedSecurity ;
    rdfs:comment "Narrow sense of 'ABS': backed by consumer loans/receivables other than mortgages." .

fis:HomeEquityLoanABS a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:ConsumerAssetBackedSecurity
        [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:HomeEquityLoan ] ) ] .
fis:AutoLoanABS a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:ConsumerAssetBackedSecurity
        [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:AutoLoan ] ) ] .
fis:CreditCardABS a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:ConsumerAssetBackedSecurity
        [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:CreditCardReceivable ] ) ] .
fis:StudentLoanABS a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:ConsumerAssetBackedSecurity
        [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:StudentLoan ] ) ] ;
    rdfs:label "SLABS" .
owl:AllDisjointClasses [ owl:members ( fis:HomeEquityLoanABS fis:AutoLoanABS fis:CreditCardABS fis:StudentLoanABS ) ] .

fis:ClimateBond a owl:Class ; rdfs:subClassOf fis:Bond ;
    rdfs:comment "Raises finance for climate-change mitigation or adaptation projects." .
fis:SocialImpactBond a owl:Class ; rdfs:subClassOf fis:Bond ;
    rdfs:comment "Public sector repays private investors after verified improved social outcomes." .
fis:SerialBond a owl:Class ; rdfs:subClassOf fis:Bond ;
    rdfs:comment "Matures in installments over a period of time." .

### by coupon type
fis:FixedRateBond a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasCouponType ; owl:hasValue "fixed" ] ) ] .
fis:FloatingRateNote a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasCouponType ; owl:hasValue "floating" ] ) ] ;
    rdfs:label "floater" .
fis:ZeroCouponBond a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasCouponType ; owl:hasValue "zero" ] ) ] ;
    rdfs:label "discount bond" , "deep discount bond" .
owl:AllDisjointClasses [ owl:members ( fis:FixedRateBond fis:FloatingRateNote fis:ZeroCouponBond ) ] .

fis:InflationIndexedBond a owl:Class ; rdfs:subClassOf fis:Bond ;
    rdfs:label "linker" , "index-linked bond" ;
    rdfs:comment "Principal and interest payments are indexed to the level of consumer prices." .

### by embedded option
fis:CallableBond a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:isCallable ; owl:hasValue true ] ) ] .
fis:PutableBond a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:isPutable ; owl:hasValue true ] ) ] ;
    rdfs:label "retractable bond" .
fis:BulletBond a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:isCallable ; owl:hasValue false ]
        [ a owl:Restriction ; owl:onProperty fis:isPutable ; owl:hasValue false ] ) ] ;
    rdfs:comment "A straight bond that is neither callable nor putable." .

fis:ConvertibleBond a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:isConvertible ; owl:hasValue true ] ) ] ;
    rdfs:subClassOf fis:HybridSecurity ;
    rdfs:label "convertible note" , "convertible debenture" ;
    rdfs:comment "Lets the bondholder exchange the bond for a number of shares of the issuer's common stock." .

fis:ExchangeableBond a owl:Class ; rdfs:subClassOf fis:Bond ;
    rdfs:comment "Allows exchange to shares of a corporation other than the issuer." .

fis:MandatoryConvertibleBond a owl:Class ; rdfs:subClassOf fis:ConvertibleBond ;
    rdfs:comment "Forces the holder to convert into shares at maturity." .
fis:PackagedConvertibleBond a owl:Class ; rdfs:subClassOf fis:ConvertibleBond ;
    rdfs:comment "A straight bond and a call option/warrant wrapped together, tradeable separately." .
fis:ContingentConvertibleBond a owl:Class ; rdfs:subClassOf fis:ConvertibleBond ;
    rdfs:label "CoCo" ;
    rdfs:comment "Automatically converts to equity if a pre-specified trigger event occurs." .
fis:SyntheticConvertibleBond a owl:Class ; rdfs:subClassOf fis:ConvertibleBond ;
    rdfs:comment "Issued by an investment bank to replicate a convertible payoff on a specific underlying equity; cash-settled." .

### by registration form (reusing the Security-level dimension)
fis:BearerBond a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond fis:BearerSecurity ) ] .
fis:RegisteredBond a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond fis:RegisteredSecurity ) ] .
fis:BookEntryBond a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond fis:NonCertificatedSecurity ) ] .

### by seniority
fis:SeniorBond a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasSeniorityRank ; owl:hasValue "senior" ] ) ] .
fis:SubordinatedBond a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasSeniorityRank ; owl:hasValue "subordinated" ] ) ] .
owl:AllDisjointClasses [ owl:members ( fis:SeniorBond fis:SubordinatedBond ) ] .

### by credit quality
fis:InvestmentGradeBond a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasCreditRatingCategory ; owl:hasValue "investment-grade" ] ) ] .
fis:HighYieldBond a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasCreditRatingCategory ; owl:hasValue "high-yield" ] ) ] ;
    rdfs:label "junk bond" .
owl:AllDisjointClasses [ owl:members ( fis:InvestmentGradeBond fis:HighYieldBond ) ] .

### by term length (reused for PreferredStock too)
fis:ShortTermBond a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasTermLength ; owl:hasValue "short" ] ) ] .
fis:MediumTermBond a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasTermLength ; owl:hasValue "medium" ] ) ] .
fis:LongTermBond a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasTermLength ; owl:hasValue "long" ] ) ] .
fis:PerpetualBond a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasTermLength ; owl:hasValue "perpetual" ] ) ] ;
    rdfs:label "perpetuity" , "perp" .
owl:AllDisjointClasses [ owl:members ( fis:ShortTermBond fis:MediumTermBond fis:LongTermBond fis:PerpetualBond ) ] .

#################################################################
#  MONEY MARKET / EURO DEBT
#################################################################

fis:MoneyMarketInstrument a owl:Class ; rdfs:subClassOf fis:DebtSecurity ;
    rdfs:comment "Short-term debt instrument with original maturity of one year or less." .
fis:CommercialPaper a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument ;
    rdfs:comment "Unsecured promissory note with fixed maturity usually less than 270 days." .
fis:BankersAcceptance a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument .

fis:EuroDebtSecurity a owl:Class ; rdfs:subClassOf fis:DebtSecurity ;
    rdfs:comment "Issued internationally outside the issuer's domestic market in a different denomination." .
fis:Eurobond a owl:Class ; rdfs:subClassOf fis:EuroDebtSecurity ;
    rdfs:comment "Underwritten, unsecured, interest paid gross." .
fis:Euronote a owl:Class ; rdfs:subClassOf fis:EuroDebtSecurity .

#################################################################
#  EQUITY
#################################################################

fis:CommonStock a owl:Class ; rdfs:subClassOf fis:EquitySecurity ;
    rdfs:label "ordinary share" , "voting share" .
fis:PreferredStock a owl:Class ; rdfs:subClassOf fis:EquitySecurity , fis:HybridSecurity ;
    rdfs:label "preference share" , "preferred share" ;
    rdfs:comment "Senior to common stock, subordinate to bonds; generally considered a hybrid instrument." .
owl:AllDisjointClasses [ owl:members ( fis:CommonStock fis:PreferredStock ) ] .

fis:CumulativePreferredStock a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:PreferredStock
        [ a owl:Restriction ; owl:onProperty fis:hasCumulativeDividend ; owl:hasValue true ] ) ] .
fis:NonCumulativePreferredStock a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:PreferredStock
        [ a owl:Restriction ; owl:onProperty fis:hasCumulativeDividend ; owl:hasValue false ] ) ] ;
    rdfs:label "straight preferred stock" .
owl:AllDisjointClasses [ owl:members ( fis:CumulativePreferredStock fis:NonCumulativePreferredStock ) ] .

fis:ConvertiblePreferredStock a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:PreferredStock
        [ a owl:Restriction ; owl:onProperty fis:isConvertible ; owl:hasValue true ] ) ] .

fis:PerpetualNoncumulativePreferredStock a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:PreferredStock
        [ a owl:Restriction ; owl:onProperty fis:hasCumulativeDividend ; owl:hasValue false ]
        [ a owl:Restriction ; owl:onProperty fis:hasTermLength ; owl:hasValue "perpetual" ] ) ] ;
    rdfs:comment "May be included as Tier 1 regulatory capital." .
fis:PerpetualCumulativePreferredStock a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:PreferredStock
        [ a owl:Restriction ; owl:onProperty fis:hasCumulativeDividend ; owl:hasValue true ]
        [ a owl:Restriction ; owl:onProperty fis:hasTermLength ; owl:hasValue "perpetual" ] ) ] ;
    rdfs:comment "Upper Tier 2 capital." .
fis:DatedPreferredStock a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:PreferredStock
        [ a owl:Restriction ; owl:onProperty fis:hasTermLength ; owl:hasValue "dated" ] ) ] ;
    rdfs:comment "Normally original maturity of at least five years; Lower Tier 2 capital." .

fis:DepositaryReceipt a owl:Class ; rdfs:subClassOf fis:EquitySecurity ;
    rdfs:comment "Negotiable instrument issued by a bank representing a foreign company's publicly traded securities." .
fis:AmericanDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt ; rdfs:label "ADR" .
fis:EuropeanDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt ; rdfs:label "EDR" .
fis:GlobalDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt ; rdfs:label "GDR" .
owl:AllDisjointClasses [ owl:members ( fis:AmericanDepositaryReceipt fis:EuropeanDepositaryReceipt fis:GlobalDepositaryReceipt ) ] .

#################################################################
#  DERIVATIVES
#################################################################

fis:Forward a owl:Class ; rdfs:subClassOf fis:Derivative .
fis:Future a owl:Class ; rdfs:subClassOf fis:Derivative .
fis:Option a owl:Class ; rdfs:subClassOf fis:Derivative .
fis:Swap a owl:Class ; rdfs:subClassOf fis:Derivative .
owl:AllDisjointClasses [ owl:members ( fis:Forward fis:Future fis:Option fis:Swap ) ] .

fis:LockProduct a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Derivative
        [ a owl:Restriction ; owl:onProperty fis:hasObligationToPerform ; owl:hasValue true ] ) ] .
fis:OptionProduct a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Derivative
        [ a owl:Restriction ; owl:onProperty fis:hasObligationToPerform ; owl:hasValue false ] ) ] .
owl:AllDisjointClasses [ owl:members ( fis:LockProduct fis:OptionProduct ) ] .
fis:Forward rdfs:subClassOf fis:LockProduct .
fis:Future rdfs:subClassOf fis:LockProduct .
fis:Swap rdfs:subClassOf fis:LockProduct .
fis:Option rdfs:subClassOf fis:OptionProduct .

fis:ExchangeTradedDerivative a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Derivative
        [ a owl:Restriction ; owl:onProperty fis:isExchangeTraded ; owl:hasValue true ] ) ] .
fis:OverTheCounterDerivative a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Derivative
        [ a owl:Restriction ; owl:onProperty fis:isExchangeTraded ; owl:hasValue false ] ) ] ;
    rdfs:label "OTC derivative" .
owl:AllDisjointClasses [ owl:members ( fis:ExchangeTradedDerivative fis:OverTheCounterDerivative ) ] .

fis:ForwardRateAgreement a owl:Class ; rdfs:subClassOf fis:Forward ; rdfs:label "FRA" .

fis:StockFuture a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Future
        [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:EquitySecurity ] ) ] .
fis:StockIndexFuture a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Future
        [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:PriceIndex ] ) ] .

### Options
fis:CallOption a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
        [ a owl:Restriction ; owl:onProperty fis:hasRightToBuy ; owl:hasValue true ] ) ] ;
    rdfs:comment "The right, not the obligation, to buy the underlying at the strike price." .
fis:PutOption a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
        [ a owl:Restriction ; owl:onProperty fis:hasRightToBuy ; owl:hasValue false ] ) ] ;
    rdfs:comment "The right, not the obligation, to sell the underlying at the strike price." .
owl:AllDisjointClasses [ owl:members ( fis:CallOption fis:PutOption ) ] .

fis:AmericanOption a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
        [ a owl:Restriction ; owl:onProperty fis:hasExerciseStyle ; owl:hasValue "American" ] ) ] ;
    rdfs:comment "May be exercised on any trading day on or before expiration." .
fis:EuropeanOption a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
        [ a owl:Restriction ; owl:onProperty fis:hasExerciseStyle ; owl:hasValue "European" ] ) ] ;
    rdfs:comment "May only be exercised on expiry." .
fis:BermudanOption a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
        [ a owl:Restriction ; owl:onProperty fis:hasExerciseStyle ; owl:hasValue "Bermudan" ] ) ] ;
    rdfs:comment "May be exercised only on specified dates on or before expiration." .
owl:AllDisjointClasses [ owl:members ( fis:AmericanOption fis:EuropeanOption fis:BermudanOption ) ] .

fis:AsianOption a owl:Class ; rdfs:subClassOf fis:Option ;
    rdfs:comment "Payoff determined by the average underlying price over a preset period." .
fis:BarrierOption a owl:Class ; rdfs:subClassOf fis:Option ;
    rdfs:comment "Underlying price must pass a barrier level before it can be exercised." .
fis:BinaryOption a owl:Class ; rdfs:subClassOf fis:Option ;
    rdfs:comment "Pays the full amount if a defined condition is met at expiration, otherwise nothing." .
fis:ExoticOption a owl:Class ; rdfs:subClassOf fis:Option ;
    rdfs:comment "Broad category of options with complex financial structures." .

fis:StockOption a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
        [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:EquitySecurity ] ) ] .
fis:BondOption a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
        [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:Bond ] ) ] .

fis:Warrant a owl:Class ; rdfs:subClassOf fis:Option ;
    rdfs:comment "Long-dated option, generally traded over the counter." .
fis:EquityWarrant a owl:Class ; rdfs:subClassOf fis:Warrant , fis:HybridSecurity ;
    rdfs:comment "Issued by a company, allowing purchase of a specific number of shares at a specified price within a specified time. Classified by the corpus both as a hybrid security and as a type of option; both parentages are retained here." .

### Swaps
fis:InterestRateSwap a owl:Class ; rdfs:subClassOf fis:Swap .
fis:CurrencySwap a owl:Class ; rdfs:subClassOf fis:Swap .
fis:CreditDefaultSwap a owl:Class ; rdfs:subClassOf fis:Swap ; rdfs:label "CDS" ;
    rdfs:comment "Seller compensates buyer in the event of default or other credit event on a reference entity's debt." .
fis:CommoditySwap a owl:Class ; rdfs:subClassOf fis:Swap .
fis:EquitySwap a owl:Class ; rdfs:subClassOf fis:Swap .
owl:AllDisjointClasses [ owl:members ( fis:InterestRateSwap fis:CurrencySwap fis:CreditDefaultSwap fis:CommoditySwap fis:EquitySwap ) ] .

#################################################################
#  INVESTMENT FUNDS
#################################################################

fis:InvestmentFund a owl:Class ; rdfs:subClassOf fis:Security ;
    rdfs:comment "Pools money from many investors to purchase other securities; the combined holdings are its portfolio." .

fis:MutualFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund .
fis:ExchangeTradedFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ; rdfs:label "ETF" .
fis:HedgeFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund .
owl:AllDisjointClasses [ owl:members ( fis:MutualFund fis:ExchangeTradedFund fis:HedgeFund ) ] .

fis:OpenEndFund a owl:Class ; rdfs:subClassOf fis:MutualFund .
fis:ClosedEndFund a owl:Class ; rdfs:subClassOf fis:MutualFund .
fis:UnitInvestmentTrust a owl:Class ; rdfs:subClassOf fis:MutualFund .
owl:AllDisjointClasses [ owl:members ( fis:OpenEndFund fis:ClosedEndFund fis:UnitInvestmentTrust ) ] .

fis:MoneyMarketFund a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:MutualFund
        [ a owl:Restriction ; owl:onProperty fis:hasPrincipalInvestmentType ; owl:hasValue "money-market" ] ) ] .
fis:BondFund a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:MutualFund
        [ a owl:Restriction ; owl:onProperty fis:hasPrincipalInvestmentType ; owl:hasValue "bond" ] ) ] ;
    rdfs:label "income fund" .
fis:EquityFund a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:MutualFund
        [ a owl:Restriction ; owl:onProperty fis:hasPrincipalInvestmentType ; owl:hasValue "equity" ] ) ] ;
    rdfs:label "stock fund" .
fis:HybridFund a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:MutualFund
        [ a owl:Restriction ; owl:onProperty fis:hasPrincipalInvestmentType ; owl:hasValue "hybrid" ] ) ] ;
    rdfs:label "balanced fund" .
owl:AllDisjointClasses [ owl:members ( fis:MoneyMarketFund fis:BondFund fis:EquityFund fis:HybridFund ) ] .

fis:IndexFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ;
    rdfs:comment "Passively managed fund that tracks the performance of an index." .
fis:ActivelyManagedFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund .
owl:AllDisjointClasses [ owl:members ( fis:IndexFund fis:ActivelyManagedFund ) ] .

fis:StockETF a owl:Class ; rdfs:subClassOf fis:ExchangeTradedFund .
fis:BondETF a owl:Class ; rdfs:subClassOf fis:ExchangeTradedFund .
fis:CommodityETF a owl:Class ; rdfs:subClassOf fis:ExchangeTradedFund .
fis:CurrencyETF a owl:Class ; rdfs:subClassOf fis:ExchangeTradedFund .
fis:RealEstateETF a owl:Class ; rdfs:subClassOf fis:ExchangeTradedFund .
fis:InverseETF a owl:Class ; rdfs:subClassOf fis:ExchangeTradedFund ;
    rdfs:comment "Designed to move opposite to its benchmark." .
fis:LeveragedETF a owl:Class ; rdfs:subClassOf fis:ExchangeTradedFund ;
    rdfs:comment "Seeks to amplify the benchmark's daily return." .
owl:AllDisjointClasses [ owl:members ( fis:StockETF fis:BondETF fis:CommodityETF fis:CurrencyETF fis:RealEstateETF fis:InverseETF fis:LeveragedETF ) ] .

fis:IndexETF a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:ExchangeTradedFund fis:IndexFund ) ] .
fis:ActivelyManagedETF a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:ExchangeTradedFund fis:ActivelyManagedFund ) ] .
