```turtle
@prefix fis:  <http://example.org/onto/securities#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .

<http://example.org/onto/securities> a owl:Ontology ;
  rdfs:label "Securities and Financial Instruments Ontology" .

#################################################################
# TOP-LEVEL CLASSES
#################################################################

fis:Asset a owl:Class ;
  rdfs:label "Asset" ;
  rdfs:comment "A resource of economic value, including commodities, currencies, indices and financial instruments." .

fis:FinancialInstrument a owl:Class ;
  rdfs:subClassOf fis:Asset ;
  rdfs:label "Financial Instrument" ;
  rdfs:comment "A monetary contract between parties that can be created, traded, modified and settled (IAS 32: gives rise to a financial asset of one entity and a financial liability or equity instrument of another)." .

fis:Commodity a owl:Class ;
  rdfs:subClassOf fis:Asset ;
  rdfs:label "Commodity" .

fis:Currency a owl:Class ;
  rdfs:subClassOf fis:Asset ;
  rdfs:label "Currency" .

fis:MarketIndex a owl:Class ;
  rdfs:subClassOf fis:Asset ;
  rdfs:label "Market Index" .

fis:InterestRateIndex a owl:Class ;
  rdfs:subClassOf fis:Asset ;
  rdfs:label "Interest Rate" .

#################################################################
# CASH vs DERIVATIVE INSTRUMENTS (top-level mutually exclusive split)
#################################################################

fis:CashInstrument a owl:Class ;
  rdfs:subClassOf fis:FinancialInstrument ;
  rdfs:label "Cash Instrument" ;
  rdfs:comment "Instrument whose value is determined directly by the markets; includes securities (readily transferable) and loans/deposits (requiring bilateral agreement to transfer)." .

fis:Derivative a owl:Class ;
  rdfs:subClassOf fis:FinancialInstrument ;
  rdfs:label "Derivative" ;
  rdfs:comment "A contract whose value is derived from the performance of an underlier (commodity, financial instrument, index, currency, interest rate, or event). NOTE: one US-law source classifies derivatives as a third broad category of 'security' alongside debt and equity securities, while another source treats 'cash instrument' (incl. securities) and 'derivative instrument' as mutually exclusive top-level categories of financial instrument. This ontology follows the latter, more structurally explicit dichotomy; the conflict is noted here." .

fis:Loan a owl:Class ;
  rdfs:subClassOf fis:CashInstrument ;
  rdfs:label "Loan" .

fis:Deposit a owl:Class ;
  rdfs:subClassOf fis:CashInstrument ;
  rdfs:label "Deposit" .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:CashInstrument fis:Derivative ) .

#################################################################
# SECURITY (defined class)
#################################################################

fis:Security a owl:Class ;
  rdfs:subClassOf fis:CashInstrument ;
  owl:equivalentClass [
    owl:intersectionOf (
      fis:FinancialInstrument
      [ a owl:Restriction ; owl:onProperty fis:isTradable ; owl:hasValue true ]
    )
  ] ;
  rdfs:label "Security" ;
  rdfs:comment "A tradable financial asset; legal definitions vary by jurisdiction." .

fis:DebtSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:label "Debt Security" ;
  rdfs:comment "Holder entitled to payment of principal and interest; may be called debenture, bond, deposit, note or commercial paper depending on maturity and collateral." .

fis:EquitySecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:label "Equity Security" ;
  rdfs:comment "A share of equity interest in an entity; residual claim after creditors are paid; generally entitles holder to control and upside." .

fis:HybridSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:label "Hybrid Security" ;
  rdfs:comment "Combines characteristics of both debt and equity securities." .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:DebtSecurity fis:EquitySecurity ) .

#################################################################
# CERTIFICATE FORM / TRANSFER MODE CLASSIFICATIONS
#################################################################

fis:BearerSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:label "Bearer Security" ;
  rdfs:comment "Entitles the holder to rights merely by holding the security; transferred by delivery." .

fis:RegisteredSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:label "Registered Security" ;
  rdfs:comment "Entitles holder to rights only if recorded on a security register; opposite of a bearer security." .

fis:BookEntrySecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:label "Book-Entry Security" ;
  rdfs:comment "Non-certificated; exists only as an electronic/dematerialized record." .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:BearerSecurity fis:RegisteredSecurity fis:BookEntrySecurity ) .

fis:DividedSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:comment "Each instrument constitutes a separate, legally distinct asset/debt." .

fis:UndividedSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:comment "The entire issue is one asset; each security is a fractional part of the whole." .

owl:disjointWith fis:DividedSecurity .

fis:DividedSecurity owl:disjointWith fis:UndividedSecurity .

fis:FungibleSecurity a owl:Class ;
  owl:equivalentClass [
    owl:intersectionOf (
      fis:Security
      [ a owl:Restriction ; owl:onProperty fis:isFungible ; owl:hasValue true ]
    )
  ] ;
  rdfs:label "Fungible Security" ;
  rdfs:comment "All holdings of the security are treated identically and are interchangeable." .

#################################################################
# SECURITY OFFERING
#################################################################

fis:SecurityOffering a owl:Class ; rdfs:label "Security Offering" .
fis:PublicOffering a owl:Class ; rdfs:subClassOf fis:SecurityOffering .
fis:PrivatePlacement a owl:Class ; rdfs:subClassOf fis:SecurityOffering .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:PublicOffering fis:PrivatePlacement ) .

#################################################################
# ISSUERS
#################################################################

fis:Issuer a owl:Class ; rdfs:label "Issuer" ;
  rdfs:comment "The company or other entity issuing the security." .

fis:Corporation a owl:Class ; rdfs:subClassOf fis:Issuer .
fis:SovereignGovernment a owl:Class ; rdfs:subClassOf fis:Issuer .
fis:Municipality a owl:Class ; rdfs:subClassOf fis:Issuer .
fis:SupranationalOrganization a owl:Class ; rdfs:subClassOf fis:Issuer .
fis:Bank a owl:Class ; rdfs:subClassOf fis:Issuer .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:Corporation fis:SovereignGovernment fis:Municipality fis:SupranationalOrganization ) .

fis:Holder a owl:Class ; rdfs:label "Holder" .

#################################################################
# CREDIT RATING
#################################################################

fis:CreditRating a owl:Class ; rdfs:label "Credit Rating" .
fis:InvestmentGradeRating a owl:Class ; rdfs:subClassOf fis:CreditRating .
fis:HighYieldRating a owl:Class ; rdfs:subClassOf fis:CreditRating .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:InvestmentGradeRating fis:HighYieldRating ) .

#################################################################
# BOND AND SUBCLASSES
#################################################################

fis:Bond a owl:Class ; rdfs:subClassOf fis:DebtSecurity ;
  rdfs:label "Bond" ;
  rdfs:comment "Issuer owes holder a debt, obliged to repay principal at maturity and usually pay periodic interest (coupon). Bond classification axes (issuer type, maturity, coupon structure, seniority form, etc.) are not mutually exclusive unless stated otherwise below." .

fis:Indenture a owl:Class ; rdfs:label "Indenture" ;
  rdfs:comment "A formal debt agreement establishing the terms of a bond issue." .

### Issuer-based bond classification (defined classes)

fis:GovernmentBond a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf (
      fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesOn fis:SovereignGovernment ]
  ) ] ;
  rdfs:label "Government Bond" ; rdfs:comment "Also called treasury/sovereign bond." .

fis:CorporateBond a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf (
      fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesOn fis:Corporation ]
  ) ] ;
  rdfs:label "Corporate Bond" .

fis:MunicipalBond a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf (
      fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesOn fis:Municipality ]
  ) ] ;
  rdfs:label "Municipal Bond" ; rdfs:comment "Known in the US as municipal bonds ('munis')." .

fis:SupranationalBond a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf (
      fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesOn fis:SupranationalOrganization ]
  ) ] ;
  rdfs:label "Supranational Bond" .

fis:GeneralObligationBond a owl:Class ; rdfs:subClassOf fis:MunicipalBond ;
  rdfs:comment "Secured by full faith/credit and taxing power of the issuer." .

fis:RevenueBond a owl:Class ; rdfs:subClassOf fis:MunicipalBond ;
  rdfs:comment "Repayment solely from revenues of a specified revenue-generating project; typically non-recourse." .

fis:WarBond a owl:Class ; rdfs:subClassOf fis:GovernmentBond .
fis:ClimateBond a owl:Class ; rdfs:subClassOf fis:Bond .
fis:SocialImpactBond a owl:Class ; rdfs:subClassOf fis:Bond .

### Credit-quality classification of corporate bonds

fis:HighYieldBond a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf (
      fis:CorporateBond
      [ a owl:Restriction ; owl:onProperty fis:hasCreditRating ; owl:someValuesOn fis:HighYieldRating ]
  ) ] ;
  rdfs:label "High-Yield Bond" ; rdfs:comment "Also called junk bond; rated below investment grade." .

fis:InvestmentGradeBond a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf (
      fis:CorporateBond
      [ a owl:Restriction ; owl:onProperty fis:hasCreditRating ; owl:someValuesOn fis:InvestmentGradeRating ]
  ) ] ;
  rdfs:label "Investment-Grade Bond" .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:HighYieldBond fis:InvestmentGradeBond ) .

### Coupon-structure classification

fis:ZeroCouponBond a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf (
      fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasCouponRate ; owl:hasValue "0"^^xsd:decimal ]
  ) ] ;
  rdfs:label "Zero-Coupon Bond" ;
  rdfs:comment "Face value repaid at maturity; no periodic interest payments; sold at a deep discount." .

fis:FixedRateBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Coupon remains constant throughout the life of the bond." .

fis:FloatingRateNote a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Coupon varies periodically based on a reference money-market rate." .

fis:InflationIndexedBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Principal and/or interest payments indexed to a price level (e.g. TIPS, I-bonds, index-linked gilts)." .

### Maturity-based classification

fis:PerpetualBond a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf (
      fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasMaturityDate ; owl:maxCardinality 0 ]
  ) ] ;
  rdfs:label "Perpetual Bond" ; rdfs:comment "Has no maturity date; a perpetuity." .

### Optionality-based classification

fis:CallableBond a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf (
      fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:isCallable ; owl:hasValue true ]
  ) ] ;
  rdfs:label "Callable Bond" ; rdfs:comment "Issuer may repay the bond before maturity on call dates." .

fis:PutableBond a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf (
      fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:isPutable ; owl:hasValue true ]
  ) ] ;
  rdfs:label "Putable Bond" ; rdfs:comment "Also called retractable bond; holder may force early repayment." .

fis:BulletBond a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf (
      fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:isCallable ; owl:hasValue false ]
      [ a owl:Restriction ; owl:onProperty fis:isPutable ; owl:hasValue false ]
  ) ] ;
  rdfs:label "Bullet Bond" ; rdfs:comment "A straight bond that is neither callable nor putable." .

### Seniority classification

fis:SeniorBond a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf (
      fis:Bond [ a owl:Restriction ; owl:onProperty fis:isSenior ; owl:hasValue true ]
  ) ] ; rdfs:label "Senior Bond" .

fis:SubordinatedBond a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf (
      fis:Bond [ a owl:Restriction ; owl:onProperty fis:isSenior ; owl:hasValue false ]
  ) ] ; rdfs:label "Subordinated Bond" .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:SeniorBond fis:SubordinatedBond ) .

### Certificate-form classification of bonds (reuse Security forms)

fis:BearerBond a owl:Class ; rdfs:subClassOf fis:Bond, fis:BearerSecurity .
fis:RegisteredBond a owl:Class ; rdfs:subClassOf fis:Bond, fis:RegisteredSecurity .
fis:BookEntryBond a owl:Class ; rdfs:subClassOf fis:Bond, fis:BookEntrySecurity .

### Convertible / hybrid bonds

fis:ConvertibleBond a owl:Class ;
  rdfs:subClassOf fis:HybridSecurity ;
  owl:equivalentClass [ owl:intersectionOf (
      fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasConversionTarget ; owl:someValuesOn fis:EquitySecurity ]
  ) ] ;
  rdfs:label "Convertible Bond" ;
  rdfs:comment "Holder may convert the bond into a specified number of shares of the issuer's common stock." .

fis:ExchangeableBond a owl:Class ; rdfs:subClassOf fis:ConvertibleBond ;
  rdfs:comment "Convertible into shares of a corporation other than the issuer." .

fis:MandatoryConvertibleBond a owl:Class ; rdfs:subClassOf fis:ConvertibleBond .
fis:ContingentConvertibleBond a owl:Class ; rdfs:subClassOf fis:ConvertibleBond .
fis:PackagedConvertible a owl:Class ; rdfs:subClassOf fis:ConvertibleBond .
fis:SyntheticConvertibleBond a owl:Class ; rdfs:subClassOf fis:ConvertibleBond .

#################################################################
# ASSET-BACKED / MORTGAGE-BACKED / CDO FAMILY
#################################################################

fis:AssetBackedSecurity a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:label "Asset-Backed Security" ;
  rdfs:comment "Umbrella term for a bond backed by a pool of assets; also sometimes used narrowly for a subset backed specifically by consumer loans/receivables (distinct from MBS/CDO in that narrower usage) -- noted conflict in terminology." .

fis:MortgageBackedSecurity a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf (
      fis:AssetBackedSecurity
      [ a owl:Restriction ; owl:onProperty fis:hasCollateralType ; owl:hasValue "mortgage" ]
  ) ] ;
  rdfs:label "Mortgage-Backed Security" .

fis:CollateralizedDebtObligation a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf (
      fis:AssetBackedSecurity
      [ a owl:Restriction ; owl:onProperty fis:hasCollateralType ; owl:hasValue "debtObligation" ]
  ) ] ;
  rdfs:label "Collateralized Debt Obligation" .

fis:CoveredBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  owl:disjointWith fis:AssetBackedSecurity ;
  rdfs:comment "Backed by mortgages/public-sector cash flows, but the assets remain on the issuer's balance sheet (unlike ABS)." .

fis:ResidentialMortgageBackedSecurity a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity .
fis:CommercialMortgageBackedSecurity a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:ResidentialMortgageBackedSecurity fis:CommercialMortgageBackedSecurity ) .

fis:CollateralizedMortgageObligation a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity ;
  rdfs:label "Collateralized Mortgage Obligation" ; rdfs:comment "Also called pay-through bond." .

fis:StrippedMortgageBackedSecurity a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity .
fis:InterestOnlyStrip a owl:Class ; rdfs:subClassOf fis:StrippedMortgageBackedSecurity .
fis:PrincipalOnlyStrip a owl:Class ; rdfs:subClassOf fis:StrippedMortgageBackedSecurity .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:InterestOnlyStrip fis:PrincipalOnlyStrip ) .

#################################################################
# MONEY MARKET INSTRUMENTS
#################################################################

fis:MoneyMarketInstrument a owl:Class ; rdfs:subClassOf fis:DebtSecurity ;
  rdfs:label "Money Market Instrument" ;
  rdfs:comment "Short-term debt instrument with original maturity of one year or less; highly liquid." .

fis:CommercialPaper a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument ;
  rdfs:comment "Unsecured promissory note, maturity usually under 270 days." .

fis:CertificateOfDeposit a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument ;
  rdfs:comment "Time deposit sold by banks/thrifts/credit unions, fixed term, generally fixed interest." .

fis:TreasuryBill a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument, fis:ZeroCouponBond, fis:GovernmentBond ;
  rdfs:comment "Matures in one year or less; bought at a discount." .

fis:TreasuryNote a owl:Class ; rdfs:subClassOf fis:GovernmentBond ;
  rdfs:comment "US Treasury security with maturity of two to ten years." .

fis:TreasuryBondLongTerm a owl:Class ; rdfs:subClassOf fis:GovernmentBond ;
  rdfs:label "Treasury Bond" ;
  rdfs:comment "US Treasury security with the longest maturity, 20-30 years." .

fis:TreasuryInflationProtectedSecurity a owl:Class ; rdfs:subClassOf fis:GovernmentBond, fis:InflationIndexedBond .

fis:RepurchaseAgreement a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument ;
  rdfs:comment "Short-term loan arranged by selling securities with an agreement to repurchase at a fixed price/date. NOTE: another passage states repurchase agreements 'defy categorization' into the cash-instrument/derivative-instrument matrix; conflict noted." .

fis:EuroDebtSecurity a owl:Class ; rdfs:subClassOf fis:DebtSecurity ;
  rdfs:comment "Issued internationally outside the domestic market, in a currency different from the issuer's domicile." .

fis:Eurobond a owl:Class ; rdfs:subClassOf fis:EuroDebtSecurity, fis:Bond .
fis:Euronote a owl:Class ; rdfs:subClassOf fis:EuroDebtSecurity, fis:MoneyMarketInstrument .

#################################################################
# EQUITY SECURITIES
#################################################################

fis:Stock a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf (
      fis:EquitySecurity
      [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesOn fis:Corporation ]
  ) ] ;
  rdfs:label "Stock" ;
  rdfs:comment "Also called share or equity; consists of the units by which ownership of a corporation is divided." .

fis:CommonStock a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf (
      fis:Stock
      [ a owl:Restriction ; owl:onProperty fis:hasVotingRight ; owl:hasValue true ]
  ) ] ;
  rdfs:label "Common Stock" ; rdfs:comment "Also called ordinary share/voting share; typically carries voting rights; lowest priority on liquidation/dividends." .

fis:PreferredStock a owl:Class ;
  rdfs:subClassOf fis:HybridSecurity ;
  owl:equivalentClass [ owl:intersectionOf (
      fis:Stock
      [ a owl:Restriction ; owl:onProperty fis:hasDividendPriority ; owl:hasValue true ]
  ) ] ;
  rdfs:label "Preferred Stock" ;
  rdfs:comment "Also called preference share; senior to common stock for dividends and liquidation, subordinate to bonds; typically non-voting." .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:CommonStock fis:PreferredStock ) .

fis:CumulativePreferredStock a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf (
      fis:PreferredStock
      [ a owl:Restriction ; owl:onProperty fis:isCumulative ; owl:hasValue true ]
  ) ] ; rdfs:label "Cumulative Preferred Stock" .

fis:NoncumulativePreferredStock a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf (
      fis:PreferredStock
      [ a owl:Restriction ; owl:onProperty fis:isCumulative ; owl:hasValue false ]
  ) ] ; rdfs:label "Noncumulative Preferred Stock" .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:CumulativePreferredStock fis:NoncumulativePreferredStock ) .

fis:ConvertiblePreferredStock a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf (
      fis:PreferredStock
      [ a owl:Restriction ; owl:onProperty fis:hasConversionTarget ; owl:someValuesOn fis:CommonStock ]
  ) ] ; rdfs:label "Convertible Preferred Stock" .

#################################################################
# WARRANTS / DEPOSITARY RECEIPTS
#################################################################

fis:EquityWarrant a owl:Class ;
  rdfs:subClassOf fis:HybridSecurity, fis:Option ;
  rdfs:label "Equity Warrant" ;
  rdfs:comment "Option issued by a company allowing the holder to purchase a specific number of shares at a specified price within a specified time; long-dated compared with ordinary options." .

fis:DepositaryReceipt a owl:Class ;
  rdfs:subClassOf fis:EquitySecurity ;
  owl:equivalentClass [ owl:intersectionOf (
      fis:Security
      [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesOn fis:Bank ]
      [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesOn fis:EquitySecurity ]
  ) ] ;
  rdfs:label "Depositary Receipt" ;
  rdfs:comment "Negotiable instrument issued by a bank representing a foreign company's publicly traded securities." .

fis:AmericanDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt .
fis:EuropeanDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt .
fis:GlobalDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:AmericanDepositaryReceipt fis:EuropeanDepositaryReceipt fis:GlobalDepositaryReceipt ) .

#################################################################
# DERIVATIVES
#################################################################

fis:LockProduct a owl:Class ; rdfs:subClassOf fis:Derivative ;
  rdfs:label "Lock Product" ;
  rdfs:comment "Obligates both contractual parties to the terms over the life of the contract (e.g. forwards, futures, swaps)." .

fis:Option a owl:Class ; rdfs:subClassOf fis:Derivative ;
  rdfs:label "Option" ;
  rdfs:comment "Gives the buyer the right, but not the obligation, to buy or sell an underlying asset at a specified strike price on or before a specified date." .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:LockProduct fis:Option ) .

fis:Forward a owl:Class ;
  rdfs:subClassOf fis:LockProduct ;
  rdfs:label "Forward" ;
  rdfs:comment "Non-standardized, non-exchange-traded contract between two parties to buy/sell an asset at a specified future time at a price agreed today." .

fis:Future a owl:Class ;
  rdfs:subClassOf fis:LockProduct ;
  rdfs:label "Future" ;
  rdfs:comment "Standardized contract traded on a futures exchange to buy/sell an asset at a predetermined price on a specified future delivery date." .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:Forward fis:Future ) .

fis:Swap a owl:Class ; rdfs:subClassOf fis:LockProduct ;
  rdfs:label "Swap" ;
  rdfs:comment "Two counterparties exchange cash flows (legs) of one financial instrument for those of another." .

fis:InterestRateSwap a owl:Class ; rdfs:subClassOf fis:Swap .
fis:CurrencySwap a owl:Class ; rdfs:subClassOf fis:Swap .

fis:CreditDerivative a owl:Class ; rdfs:subClassOf fis:Derivative ;
  rdfs:comment "Transfers credit risk from a protection buyer to a protection seller." .

fis:CreditDefaultSwap a owl:Class ; rdfs:subClassOf fis:Swap, fis:CreditDerivative ;
  rdfs:label "Credit Default Swap" ;
  rdfs:comment "Seller compensates buyer in the event of a loan default or other credit event on a reference entity." .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:InterestRateSwap fis:CurrencySwap fis:CreditDefaultSwap ) .

### Options classified by right

fis:CallOption a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf (
      fis:Option [ a owl:Restriction ; owl:onProperty fis:hasOptionRight ; owl:hasValue "buy" ]
  ) ] ; rdfs:label "Call Option" .

fis:PutOption a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf (
      fis:Option [ a owl:Restriction ; owl:onProperty fis:hasOptionRight ; owl:hasValue "sell" ]
  ) ] ; rdfs:label "Put Option" .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:CallOption fis:PutOption ) .

### Options classified by exercise style

fis:AmericanOption a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf (
      fis:Option [ a owl:Restriction ; owl:onProperty fis:hasExerciseStyle ; owl:hasValue "American" ]
  ) ] ; rdfs:comment "May be exercised on any trading day on or before expiration." .

fis:EuropeanOption a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf (
      fis:Option [ a owl:Restriction ; owl:onProperty fis:hasExerciseStyle ; owl:hasValue "European" ]
  ) ] ; rdfs:comment "May only be exercised on the expiration date." .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:AmericanOption fis:EuropeanOption ) .

fis:StockOption a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:comment "Underlying is the price of an equity (stock or stock index)." .

fis:BondOption a owl:Class ; rdfs:subClassOf fis:Option .

#################################################################
# INVESTMENT FUNDS
#################################################################

fis:InvestmentFund a owl:Class ; rdfs:subClassOf fis:FinancialInstrument ;
  rdfs:label "Investment Fund" ;
  rdfs:comment "Pools money from many investors to purchase securities, managed by a fund/portfolio manager." .

fis:MutualFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund .
fis:ExchangeTradedFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ;
  rdfs:comment "Investors buy/sell shares on an exchange at market prices, which may differ from net asset value, unlike mutual funds." .
fis:HedgeFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ;
  rdfs:comment "Pools investor money like a mutual fund but with fewer investor-protection regulations and more flexible/risky strategies." .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:MutualFund fis:ExchangeTradedFund fis:HedgeFund ) .

fis:MoneyMarketFund a owl:Class ; rdfs:subClassOf fis:MutualFund .
fis:BondFund a owl:Class ; rdfs:subClassOf fis:MutualFund .
fis:StockFund a owl:Class ; rdfs:subClassOf fis:MutualFund .
fis:HybridFund a owl:Class ; rdfs:subClassOf fis:MutualFund .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:MoneyMarketFund fis:BondFund fis:StockFund fis:HybridFund ) .

fis:IndexFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ;
  rdfs:comment "Passively managed fund that tracks the performance of an index." .
fis:ActivelyManagedFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ;
  rdfs:comment "Seeks to outperform an index; generally charges higher fees." .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:IndexFund fis:ActivelyManagedFund ) .

fis:OpenEndFund a owl:Class ; rdfs:subClassOf fis:MutualFund ;
  rdfs:comment "Shares purchased from/sold to the issuer at net asset value." .
fis:ClosedEndFund a owl:Class ; rdfs:subClassOf fis:MutualFund .
fis:UnitInvestmentTrust a owl:Class ; rdfs:subClassOf fis:MutualFund .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:OpenEndFund fis:ClosedEndFund fis:UnitInvestmentTrust ) .

#################################################################
# OBJECT PROPERTIES
#################################################################

fis:hasIssuer a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Security ; rdfs:range fis:Issuer ;
  rdfs:label "hasIssuer" .

fis:isIssuerOf a owl:ObjectProperty ;
  owl:inverseOf fis:hasIssuer ;
  rdfs:domain fis:Issuer ; rdfs:range fis:Security .

fis:hasUnderlying a owl:ObjectProperty ;
  rdfs:domain fis:Derivative ; rdfs:range fis:Asset ;
  rdfs:label "hasUnderlying" .

fis:isUnderlyingOf a owl:ObjectProperty ;
  owl:inverseOf fis:hasUnderlying ;
  rdfs:domain fis:Asset ; rdfs:range fis:Derivative .

fis:hasConversionTarget a owl:ObjectProperty ;
  rdfs:domain fis:HybridSecurity ; rdfs:range fis:EquitySecurity ;
  rdfs:label "hasConversionTarget" .

fis:hasReferenceEntity a owl:ObjectProperty ;
  rdfs:domain fis:CreditDefaultSwap ; rdfs:range fis:Issuer .

fis:hasCreditRating a owl:ObjectProperty ;
  rdfs:domain fis:Security ; rdfs:range fis:CreditRating .

fis:hasOfferingType a owl:ObjectProperty ;
  rdfs:domain fis:Security ; rdfs:range fis:SecurityOffering .

fis:hasHolder a owl:ObjectProperty ;
  rdfs:domain fis:Security ; rdfs:range fis:Holder .

fis:isHolderOf a owl:ObjectProperty ;
  owl:inverseOf fis:hasHolder ;
  rdfs:domain fis:Holder ; rdfs:range fis:Security .

fis:hasIndenture a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Bond ; rdfs:range fis:Indenture .

#################################################################
# DATATYPE PROPERTIES
#################################################################

fis:isTradable a owl:DatatypeProperty ;
  rdfs:domain fis:FinancialInstrument ; rdfs:range xsd:boolean .

fis:isFungible a owl:DatatypeProperty ;
  rdfs:domain fis:Security ; rdfs:range xsd:boolean .

fis:isExchangeTraded a owl:DatatypeProperty ;
  rdfs:domain fis:FinancialInstrument ; rdfs:range xsd:boolean .

fis:isStandardized a owl:DatatypeProperty ;
  rdfs:domain fis:Derivative ; rdfs:range xsd:boolean .

fis:hasMaturityDate a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:DebtSecurity ; rdfs:range xsd:date ;
  rdfs:label "hasMaturityDate" ;
  rdfs:comment "Synonyms: maturity, tenor, term." .

fis:hasFaceValue a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:DebtSecurity ; rdfs:range xsd:decimal ;
  rdfs:label "hasFaceValue" ;
  rdfs:comment "Synonyms: par value, principal, nominal amount." .

fis:hasCouponRate a owl:DatatypeProperty ;
  rdfs:domain fis:Bond ; rdfs:range xsd:decimal ;
  rdfs:comment "Interest rate the issuer pays to the holder, expressed annually." .

fis:hasYield a owl:DatatypeProperty ;
  rdfs:domain fis:Bond ; rdfs:range xsd:decimal .

fis:hasReferenceRate a owl:DatatypeProperty ;
  rdfs:domain fis:Bond ; rdfs:range xsd:string .

fis:isCallable a owl:DatatypeProperty ;
  rdfs:domain fis:Bond ; rdfs:range xsd:boolean .

fis:isPutable a owl:DatatypeProperty ;
  rdfs:domain fis:Bond ; rdfs:range xsd:boolean .

fis:isSenior a owl:DatatypeProperty ;
  rdfs:domain fis:Bond ; rdfs:range xsd:boolean .

fis:hasCollateralType a owl:DatatypeProperty ;
  rdfs:domain fis:AssetBackedSecurity ; rdfs:range xsd:string .

fis:hasVotingRight a owl:DatatypeProperty ;
  rdfs:domain fis:Stock ; rdfs:range xsd:boolean .

fis:hasDividendPriority a owl:DatatypeProperty ;
  rdfs:domain fis:Stock ; rdfs:range xsd:boolean .

fis:isCumulative a owl:DatatypeProperty ;
  rdfs:domain fis:PreferredStock ; rdfs:range xsd:boolean .

fis:hasDividendRate a owl:DatatypeProperty ;
  rdfs:domain fis:Stock ; rdfs:range xsd:decimal .

fis:hasStrikePrice a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Option ; rdfs:range xsd:decimal ;
  rdfs:comment "Synonym: exercise price." .

fis:hasExpirationDate a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Option ; rdfs:range xsd:date ;
  rdfs:comment "Synonym: expiry, maturity date (of the option)." .

fis:hasPremium a owl:DatatypeProperty ;
  rdfs:domain fis:Option ; rdfs:range xsd:decimal .

fis:hasOptionRight a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Option ; rdfs:range xsd:string ;
