```turtle
@prefix fis:  <http://example.org/onto/securities#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .

<http://example.org/onto/securities> a owl:Ontology ;
    rdfs:label "Securities and Financial Instruments Ontology" ;
    rdfs:comment "An ontology of securities, debt, equity, hybrid and derivative financial instruments, built from corpus text describing market practice (Wikipedia-style sources), accounting standards (IAS 32 / IFRS 9), regulatory glossaries (ECB, SEC, FINRA, BIS) and textbook material (OpenStax, CFI)." .

#################################################################
# TOP LEVEL: FINANCIAL INSTRUMENT
#################################################################

fis:FinancialInstrument a owl:Class ;
    rdfs:label "financial instrument" ;
    rdfs:comment "A monetary contract between parties that can be created, traded, modified and settled; cash, evidence of ownership, or a contractual right/obligation to deliver or receive value. IAS 32/39 define it as any contract that gives rise to a financial asset of one entity and a financial liability or equity instrument of another entity." .

fis:hasInstrumentCategory a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:label "has instrument category" ;
    rdfs:domain fis:FinancialInstrument ;
    rdfs:range xsd:string ;
    rdfs:comment "Takes value 'cash' or 'derivative', per the corpus split of financial instruments into cash instruments and derivative instruments." .

fis:CashInstrument a owl:Class ;
    rdfs:subClassOf fis:FinancialInstrument ;
    rdfs:label "cash instrument" ;
    rdfs:comment "An instrument whose value is determined directly by the markets; includes securities (readily transferable) and instruments such as loans and deposits (requiring agreement to transfer)." ;
    owl:equivalentClass [ a owl:Class ;
        owl:intersectionOf ( fis:FinancialInstrument
            [ a owl:Restriction ; owl:onProperty fis:hasInstrumentCategory ; owl:hasValue "cash" ]
        )
    ] .

fis:Derivative a owl:Class ;
    rdfs:subClassOf fis:FinancialInstrument ;
    rdfs:label "derivative" , "derivative instrument" ;
    rdfs:comment "A contract between a buyer and seller whose value is derived from the performance of an underlier (commodity, financial instrument, price index, currency or interest rate). IFRS 9 additionally characterises a derivative as requiring little or no initial net investment and settling at a future date. NOTE: the U.S. legal definition of 'security' treats derivatives as one of three security categories (debt, equity, derivatives), which conflicts with the cash/derivative-instrument split modelled here; the latter, more common framing is adopted and the conflict is noted." ;
    owl:equivalentClass [ a owl:Class ;
        owl:intersectionOf ( fis:FinancialInstrument
            [ a owl:Restriction ; owl:onProperty fis:hasInstrumentCategory ; owl:hasValue "derivative" ]
        )
    ] .

[] a owl:AllDisjointClasses ; owl:members ( fis:CashInstrument fis:Derivative ) .

#################################################################
# SECURITY
#################################################################

fis:Security a owl:Class ;
    rdfs:subClassOf fis:CashInstrument ;
    rdfs:label "security" ;
    rdfs:comment "A tradable financial asset; a negotiable and fungible instrument representing a claim on an issuer, enforceable by law. May be represented by a certificate or exist in non-certificated (electronic/book-entry) form. A simpler conflicting corpus definition states 'a security is a financial contract which entitles the holder to investment returns'; both are reflected here, with the tradable-asset view treated as primary." .

fis:hasSecurityCategory a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:label "has security category" ;
    rdfs:domain fis:Security ;
    rdfs:range xsd:string ;
    rdfs:comment "Takes value 'debt', 'equity' or 'hybrid'." .

fis:DebtSecurity a owl:Class ;
    rdfs:subClassOf fis:Security ;
    rdfs:label "debt security" ;
    rdfs:comment "A security under which the holder is entitled to payment of principal and interest and other contractual rights; may be called debentures, bonds, deposits, notes or commercial paper depending on maturity, collateral and other characteristics." ;
    owl:equivalentClass [ a owl:Class ;
        owl:intersectionOf ( fis:Security [ a owl:Restriction ; owl:onProperty fis:hasSecurityCategory ; owl:hasValue "debt" ] )
    ] .

fis:EquitySecurity a owl:Class ;
    rdfs:subClassOf fis:Security ;
    rdfs:label "equity security" ;
    rdfs:comment "A share of equity interest in an entity such as the capital stock of a company, trust or partnership; holders share only the residual interest after creditors are paid but generally receive pro-rata control and profit upside." ;
    owl:equivalentClass [ a owl:Class ;
        owl:intersectionOf ( fis:Security [ a owl:Restriction ; owl:onProperty fis:hasSecurityCategory ; owl:hasValue "equity" ] )
    ] .

fis:HybridSecurity a owl:Class ;
    rdfs:subClassOf fis:Security ;
    rdfs:label "hybrid security" ;
    rdfs:comment "A security combining characteristics of both debt and equity securities, e.g. preference shares, convertibles and warrants." ;
    owl:equivalentClass [ a owl:Class ;
        owl:intersectionOf ( fis:Security [ a owl:Restriction ; owl:onProperty fis:hasSecurityCategory ; owl:hasValue "hybrid" ] )
    ] .

[] a owl:AllDisjointClasses ; owl:members ( fis:DebtSecurity fis:EquitySecurity fis:HybridSecurity ) .

#################################################################
# SECURITY-LEVEL CROSS-CUTTING CLASSIFICATIONS
#################################################################

fis:hasOwnershipForm a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:label "has ownership form" ;
    rdfs:domain fis:Security ; rdfs:range xsd:string ;
    rdfs:comment "Takes value 'bearer', 'registered' or 'book-entry'." .

fis:BearerSecurity a owl:Class ;
    rdfs:subClassOf fis:Security ;
    rdfs:label "bearer security" ;
    rdfs:comment "Certificate entitling the holder to rights merely by holding it; completely negotiable, transferred by delivery (and sometimes endorsement)." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security [ a owl:Restriction ; owl:onProperty fis:hasOwnershipForm ; owl:hasValue "bearer" ] ) ] .

fis:RegisteredSecurity a owl:Class ;
    rdfs:subClassOf fis:Security ;
    rdfs:label "registered security" ;
    rdfs:comment "Entitles the holder to rights only if registered on a security register maintained by the issuer or an intermediary." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security [ a owl:Restriction ; owl:onProperty fis:hasOwnershipForm ; owl:hasValue "registered" ] ) ] .

fis:BookEntrySecurity a owl:Class ;
    rdfs:subClassOf fis:Security ;
    rdfs:label "book-entry security" ;
    rdfs:comment "A security with no paper certificate, existing only as an electronic record." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security [ a owl:Restriction ; owl:onProperty fis:hasOwnershipForm ; owl:hasValue "book-entry" ] ) ] .

[] a owl:AllDisjointClasses ; owl:members ( fis:BearerSecurity fis:RegisteredSecurity fis:BookEntrySecurity ) .

fis:hasDivisibility a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:label "has divisibility" ; rdfs:domain fis:Security ; rdfs:range xsd:string ;
    rdfs:comment "Takes value 'divided' or 'undivided'." .

fis:DividedSecurity a owl:Class ;
    rdfs:subClassOf fis:Security ;
    rdfs:label "divided security" ;
    rdfs:comment "Each instrument constitutes a separate asset and a separate covenant/debt of the issuer, legally distinct from other securities in the same issue." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security [ a owl:Restriction ; owl:onProperty fis:hasDivisibility ; owl:hasValue "divided" ] ) ] .

fis:UndividedSecurity a owl:Class ;
    rdfs:subClassOf fis:Security ;
    rdfs:label "undivided security" ;
    rdfs:comment "The entire issue makes up one single asset, each security being a fractional part of this undivided whole; shares in secondary markets and registered debt securities are always undivided." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security [ a owl:Restriction ; owl:onProperty fis:hasDivisibility ; owl:hasValue "undivided" ] ) ] .

[] a owl:AllDisjointClasses ; owl:members ( fis:DividedSecurity fis:UndividedSecurity ) .

fis:hasFungibility a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:label "has fungibility" ; rdfs:domain fis:Security ; rdfs:range xsd:boolean .

fis:FungibleSecurity a owl:Class ;
    rdfs:subClassOf fis:Security ;
    rdfs:label "fungible security" ;
    rdfs:comment "A security of which all holdings are treated identically and are interchangeable." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security [ a owl:Restriction ; owl:onProperty fis:hasFungibility ; owl:hasValue true ] ) ] .

fis:hasOfferingType a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:label "has offering type" ; rdfs:domain fis:Security ; rdfs:range xsd:string ;
    rdfs:comment "Takes value 'public' or 'private', per primary-market offering method." .

fis:PubliclyOfferedSecurity a owl:Class ;
    rdfs:subClassOf fis:Security ; rdfs:label "publicly offered security" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security [ a owl:Restriction ; owl:onProperty fis:hasOfferingType ; owl:hasValue "public" ] ) ] .

fis:PrivatelyPlacedSecurity a owl:Class ;
    rdfs:subClassOf fis:Security ; rdfs:label "privately placed security" ;
    rdfs:comment "Offered privately to a limited number of qualified persons; not publicly tradable, secondary market far less liquid." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security [ a owl:Restriction ; owl:onProperty fis:hasOfferingType ; owl:hasValue "private" ] ) ] .

[] a owl:AllDisjointClasses ; owl:members ( fis:PubliclyOfferedSecurity fis:PrivatelyPlacedSecurity ) .

#################################################################
# ISSUERS, HOLDERS, INVESTORS
#################################################################

fis:Issuer a owl:Class ;
    rdfs:label "issuer" ;
    rdfs:comment "The entity obligated on a security; the company or other entity issuing the security." .

fis:Corporation a owl:Class ; rdfs:subClassOf fis:Issuer ; rdfs:label "corporation" .
fis:SovereignGovernment a owl:Class ; rdfs:subClassOf fis:Issuer ; rdfs:label "sovereign government" .
fis:Municipality a owl:Class ; rdfs:subClassOf fis:Issuer ;
    rdfs:label "municipality" ;
    rdfs:comment "A local authority, state, provincial, territorial or other governmental unit other than a sovereign government." .
fis:SupranationalOrganization a owl:Class ; rdfs:subClassOf fis:Issuer ;
    rdfs:label "supranational organization" ;
    rdfs:comment "An international organization such as the World Bank, IMF or a regional multilateral development bank." .

[] a owl:AllDisjointClasses ; owl:members ( fis:Corporation fis:SovereignGovernment fis:Municipality fis:SupranationalOrganization ) .

fis:Holder a owl:Class ;
    rdfs:label "holder" ;
    rdfs:comment "An entity entitled to rights under a security." .

fis:Shareholder a owl:Class ; rdfs:subClassOf fis:Holder ;
    rdfs:label "shareholder" , "stockholder" ;
    rdfs:comment "An individual or company that legally owns one or more shares of stock in a joint stock company." .

fis:Bondholder a owl:Class ; rdfs:subClassOf fis:Holder ;
    rdfs:label "bondholder" ;
    rdfs:comment "The creditor to whom a bond issuer owes a debt." .

fis:Investor a owl:Class ; rdfs:subClassOf fis:Holder ;
    rdfs:label "investor" .

fis:hasInvestorType a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:label "has investor type" ; rdfs:domain fis:Investor ; rdfs:range xsd:string ;
    rdfs:comment "Takes value 'retail' or 'wholesale'." .

fis:RetailInvestor a owl:Class ; rdfs:subClassOf fis:Investor ;
    rdfs:label "retail investor" ;
    rdfs:comment "A member of the public investing personally, other than by way of business." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Investor [ a owl:Restriction ; owl:onProperty fis:hasInvestorType ; owl:hasValue "retail" ] ) ] .

fis:InstitutionalInvestor a owl:Class ; rdfs:subClassOf fis:Investor ;
    rdfs:label "institutional investor" , "wholesale investor" ;
    rdfs:comment "A financial institution acting on its own account or on behalf of clients, e.g. investment banks, insurance companies, pension funds." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Investor [ a owl:Restriction ; owl:onProperty fis:hasInvestorType ; owl:hasValue "wholesale" ] ) ] .

[] a owl:AllDisjointClasses ; owl:members ( fis:RetailInvestor fis:InstitutionalInvestor ) .

#################################################################
# CORE OBJECT PROPERTIES
#################################################################

fis:hasIssuer a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:label "has issuer" ;
    rdfs:domain fis:Security ; rdfs:range fis:Issuer ;
    rdfs:comment "Relates a security to the single entity issuing it." .

fis:isIssuerOf a owl:ObjectProperty ;
    rdfs:label "is issuer of" ;
    owl:inverseOf fis:hasIssuer ;
    rdfs:domain fis:Issuer ; rdfs:range fis:Security .

fis:hasHolder a owl:ObjectProperty ;
    rdfs:label "has holder" ;
    rdfs:domain fis:Security ; rdfs:range fis:Holder .

fis:isHolderOf a owl:ObjectProperty ;
    rdfs:label "is holder of" ;
    owl:inverseOf fis:hasHolder ;
    rdfs:domain fis:Holder ; rdfs:range fis:Security .

fis:Underlier a owl:Class ;
    rdfs:label "underlier" ;
    rdfs:comment "The item (financial instrument, commodity, index, currency, interest rate, or factual event/measure of economic value) on which a derivative's value depends." .

fis:FinancialInstrument rdfs:subClassOf fis:Underlier .

fis:Commodity a owl:Class ; rdfs:subClassOf fis:Underlier ; rdfs:label "commodity" .
fis:Index a owl:Class ; rdfs:subClassOf fis:Underlier ; rdfs:label "index" .
fis:Currency a owl:Class ; rdfs:subClassOf fis:Underlier ; rdfs:label "currency" .
fis:InterestRateBenchmark a owl:Class ; rdfs:subClassOf fis:Underlier ; rdfs:label "interest rate benchmark" .

fis:hasUnderlying a owl:ObjectProperty ;
    rdfs:label "has underlying" ;
    rdfs:domain fis:Derivative ; rdfs:range fis:Underlier .

fis:isUnderlyingOf a owl:ObjectProperty ;
    rdfs:label "is underlying of" ;
    owl:inverseOf fis:hasUnderlying ;
    rdfs:domain fis:Underlier ; rdfs:range fis:Derivative .

fis:Asset a owl:Class ;
    rdfs:label "asset" ;
    rdfs:comment "A generic asset (e.g. mortgage, loan, receivable) used as collateral backing a debt security." .

fis:Mortgage a owl:Class ; rdfs:subClassOf fis:Asset ; rdfs:label "mortgage" .

fis:hasCollateral a owl:ObjectProperty ;
    rdfs:label "has collateral" ;
    rdfs:domain fis:DebtSecurity ; rdfs:range fis:Asset .

fis:Market a owl:Class ; rdfs:label "market" .
fis:Exchange a owl:Class ; rdfs:subClassOf fis:Market ;
    rdfs:label "exchange" ;
    rdfs:comment "An organized and officially recognized market, e.g. a stock exchange or derivatives exchange." .
fis:OverTheCounterMarket a owl:Class ; rdfs:subClassOf fis:Market ;
    rdfs:label "over-the-counter market" ;
    rdfs:comment "A market in which buyers and sellers deal directly with each other, by telephone or electronically, without a centralized exchange." .

[] a owl:AllDisjointClasses ; owl:members ( fis:Exchange fis:OverTheCounterMarket ) .

fis:PrimaryMarket a owl:Class ; rdfs:subClassOf fis:Market ;
    rdfs:label "primary market" ;
    rdfs:comment "Market in which new securities are offered to the public or placed privately." .
fis:SecondaryMarket a owl:Class ; rdfs:subClassOf fis:Market ;
    rdfs:label "secondary market" ;
    rdfs:comment "Market for already-issued securities." .

[] a owl:AllDisjointClasses ; owl:members ( fis:PrimaryMarket fis:SecondaryMarket ) .

fis:hasTradingVenue a owl:ObjectProperty ;
    rdfs:label "has trading venue" ;
    rdfs:domain fis:Security ; rdfs:range fis:Market .

#################################################################
# DEBT SECURITY / BOND
#################################################################

fis:hasMaturityDate a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:label "has maturity date" ; rdfs:domain fis:Bond ; rdfs:range xsd:date ;
    rdfs:comment "The date on which the issuer is obligated to repay the nominal (face) amount." .

fis:hasFaceValue a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:label "has face value" ; rdfs:domain fis:Bond ; rdfs:range xsd:decimal ;
    rdfs:comment "The nominal, principal, par or face amount on which the issuer pays interest and which is repaid at maturity." .

fis:hasRedemptionAmount a owl:DatatypeProperty ;
    rdfs:label "has redemption amount" ; rdfs:domain fis:Bond ; rdfs:range xsd:decimal ;
    rdfs:comment "For some structured bonds, a redemption amount that differs from the face amount, linked to the performance of particular assets." .

fis:hasCouponRate a owl:DatatypeProperty ;
    rdfs:label "has coupon rate" ; rdfs:domain fis:Bond ; rdfs:range xsd:decimal ;
    rdfs:comment "The interest rate the issuer pays to the holder." .

fis:hasOriginalTermInDays a owl:DatatypeProperty ;
    rdfs:label "has original term in days" ; rdfs:domain fis:DebtSecurity ; rdfs:range xsd:integer .

fis:hasCreditRating a owl:ObjectProperty ;
    rdfs:label "has credit rating" ;
    rdfs:comment "Relates a bond to a credit-rating assessment by a rating agency." .

fis:Bond a owl:Class ;
    rdfs:subClassOf fis:DebtSecurity ;
    rdfs:label "bond" ;
    rdfs:comment "A security under which the issuer owes the holder a debt and is obliged to repay principal at maturity plus interest (coupon) over a specified time; a form of loan or IOU." .

fis:EmbeddedOptionFeature a owl:Class ;
    rdfs:label "embedded option feature" ;
    rdfs:comment "An option-like feature granted to the holder or issuer of a bond." .

fis:CallProvision a owl:Class ; rdfs:subClassOf fis:EmbeddedOptionFeature ;
    rdfs:label "call provision" ;
    rdfs:comment "Gives the issuer the right to repay the bond before maturity on call dates." .

fis:PutProvision a owl:Class ; rdfs:subClassOf fis:EmbeddedOptionFeature ;
    rdfs:label "put provision" ;
    rdfs:comment "Gives the holder the right to force the issuer to repay the bond before maturity on put dates." .

[] a owl:AllDisjointClasses ; owl:members ( fis:CallProvision fis:PutProvision ) .

fis:hasEmbeddedOption a owl:ObjectProperty ;
    rdfs:label "has embedded option" ;
    rdfs:domain fis:Bond ; rdfs:range fis:EmbeddedOptionFeature .

fis:CallableBond a owl:Class ;
    rdfs:subClassOf fis:Bond ; rdfs:label "callable bond" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond [ a owl:Restriction ; owl:onProperty fis:hasEmbeddedOption ; owl:someValuesFrom fis:CallProvision ] ) ] .

fis:PutableBond a owl:Class ;
    rdfs:subClassOf fis:Bond ; rdfs:label "putable bond" , "retractable bond" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond [ a owl:Restriction ; owl:onProperty fis:hasEmbeddedOption ; owl:someValuesFrom fis:PutProvision ] ) ] .

fis:BulletBond a owl:Class ;
    rdfs:subClassOf fis:Bond ; rdfs:label "bullet bond" ;
    rdfs:comment "A straight bond that is neither callable nor putable." ;
    owl:equivalentClass [ a owl:Class ;
        owl:intersectionOf ( fis:Bond
            [ a owl:Class ; owl:complementOf [ a owl:Restriction ; owl:onProperty fis:hasEmbeddedOption ; owl:someValuesFrom fis:EmbeddedOptionFeature ] ]
        )
    ] .

# --- Issuer-based bond classification ---

fis:GovernmentBond a owl:Class ;
    rdfs:subClassOf fis:Bond ; rdfs:label "government bond" , "treasury bond" , "sovereign bond" ;
    rdfs:comment "Issued by a sovereign national government or its agencies." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SovereignGovernment ] ) ] .

fis:MunicipalBond a owl:Class ;
    rdfs:subClassOf fis:Bond ; rdfs:label "municipal bond" ;
    rdfs:comment "Issued by a local authority or subdivision within a country, e.g. a city or federal state." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Municipality ] ) ] .

fis:SupranationalBond a owl:Class ;
    rdfs:subClassOf fis:Bond ; rdfs:label "supranational bond" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SupranationalOrganization ] ) ] .

fis:CorporateBond a owl:Class ;
    rdfs:subClassOf fis:Bond ; rdfs:label "corporate bond" ;
    rdfs:comment "Represents the debt of commercial or industrial entities; issued to fund operations, M&A, or expansion." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Corporation ] ) ] .

[] a owl:AllDisjointClasses ; owl:members ( fis:GovernmentBond fis:MunicipalBond fis:SupranationalBond fis:CorporateBond ) .

# Municipal bond subtypes
fis:GeneralObligationBond a owl:Class ; rdfs:subClassOf fis:MunicipalBond ;
    rdfs:label "general obligation bond" ;
    rdfs:comment "Principal and interest secured by the full faith and credit of the issuer, usually supported by its taxing power." .
fis:RevenueBond a owl:Class ; rdfs:subClassOf fis:MunicipalBond ;
    rdfs:label "revenue bond" ;
    rdfs:comment "Guaranteed by repayment solely from revenues generated by a specified revenue-generating entity; typically non-recourse." .
fis:AssessmentBond a owl:Class ; rdfs:subClassOf fis:GeneralObligationBond ;
    rdfs:label "assessment bond" ;
    rdfs:comment "Repayment based on property tax assessments; a form of general obligation bond." .

[] a owl:AllDisjointClasses ; owl:members ( fis:GeneralObligationBond fis:RevenueBond ) .

# Other Bond-by-issuer-purpose/feature subclasses (coverage, lightly axiomatized)
fis:WarBond a owl:Class ; rdfs:subClassOf fis:GovernmentBond ;
    rdfs:comment "Issued by a government to fund military operations during wartime." .
fis:ClimateBond a owl:Class ; rdfs:subClassOf fis:Bond ;
    rdfs:comment "Issued to raise finance for climate change mitigation or adaptation projects." .
fis:SocialImpactBond a owl:Class ; rdfs:subClassOf fis:Bond ;
    rdfs:comment "Public sector entities pay back private investors after meeting verified social outcome goals." .
fis:CoveredBond a owl:Class ; rdfs:subClassOf fis:Bond ;
    rdfs:comment "Backed by cash flows from mortgages or public-sector assets which remain on the issuer's balance sheet (unlike asset-backed securities)." .
fis:SerialBond a owl:Class ; rdfs:subClassOf fis:Bond ;
    rdfs:comment "A bond that matures in installments over a period of time." .
fis:Methuselah a owl:Class ; rdfs:subClassOf fis:Bond ;
    rdfs:comment "A bond with a maturity of 50 years or longer." .
fis:LotteryBond a owl:Class ; rdfs:subClassOf fis:Bond ;
    rdfs:comment "Issuer redeems randomly selected individual bonds within the issue according to a schedule, sometimes above face value." .
fis:PerpetualBond a owl:Class ; rdfs:subClassOf fis:Bond ;
    rdfs:label "perpetual bond" , "perpetuity" ;
    rdfs:comment "A bond with no maturity date; principal is repaid only at the discretion of the borrower, if ever." .

# --- Seniority / collateral status ---

fis:hasSeniority a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:label "has seniority" ; rdfs:domain fis:DebtSecurity ; rdfs:range xsd:string ;
    rdfs:comment "Takes value 'senior' or 'subordinated'." .

fis:SeniorDebtSecurity a owl:Class ; rdfs:subClassOf fis:DebtSecurity ;
    rdfs:label "senior debt security" ;
    rdfs:comment "Contractually senior to other unsecured debt; priority in bankruptcy." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:DebtSecurity [ a owl:Restriction ; owl:onProperty fis:hasSeniority ; owl:hasValue "senior" ] ) ] .

fis:SubordinatedDebtSecurity a owl:Class ; rdfs:subClassOf fis:DebtSecurity ;
    rdfs:label "subordinated debt security" ;
    rdfs:comment "Debt that is not senior; lower priority than senior bonds in case of liquidation." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:DebtSecurity [ a owl:Restriction ; owl:onProperty fis:hasSeniority ; owl:hasValue "subordinated" ] ) ] .

[] a owl:AllDisjointClasses ; owl:members ( fis:SeniorDebtSecurity fis:SubordinatedDebtSecurity ) .

fis:hasCollateralStatus a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:label "has collateral status" ; rdfs:domain fis:DebtSecurity ; rdfs:range xsd:string ;
    rdfs:comment "Takes value 'secured' or 'unsecured'." .

fis:SecuredDebtSecurity a owl:Class ; rdfs:subClassOf fis:DebtSecurity ;
    rdfs:label "secured debt security" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:DebtSecurity [ a owl:Restriction ; owl:onProperty fis:hasCollateralStatus ; owl:hasValue "secured" ] ) ] .

fis:Debenture a owl:Class ; rdfs:subClassOf fis:DebtSecurity ;
    rdfs:label "debenture" , "unsecured bond" ;
    rdfs:comment "An unsecured bond, having only a general claim on the issuer's assets and cash flows." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:DebtSecurity [ a owl:Restriction ; owl:onProperty fis:hasCollateralStatus ; owl:hasValue "unsecured" ] ) ] .

[] a owl:AllDisjointClasses ; owl:members ( fis:SecuredDebtSecurity fis:Debenture ) .

# --- Credit rating category ---

fis:hasCreditRatingCategory a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:label "has credit rating category" ; rdfs:domain fis:Bond ; rdfs:range xsd:string ;
    rdfs:comment "Takes value 'investmentGrade' or 'highYield'." .

fis:InvestmentGradeBond a owl:Class ; rdfs:subClassOf fis:Bond ;
    rdfs:label "investment grade bond" , "high grade bond" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond [ a owl:Restriction ; owl:onProperty fis:hasCreditRatingCategory ; owl:hasValue "investmentGrade" ] ) ] .

fis:HighYieldBond a owl:Class ; rdfs:subClassOf fis:Bond ;
    rdfs:label "high yield bond" , "junk bond" ;
    rdfs:comment "Rated below investment grade; investors expect much higher yield to compensate for default risk." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond [ a owl:Restriction ; owl:onProperty fis:hasCreditRatingCategory ; owl:hasValue "highYield" ] ) ] .

[] a owl:AllDisjointClasses ; owl:members ( fis:InvestmentGradeBond fis:HighYieldBond ) .

# --- Coupon-type classification ---

fis:hasCouponType a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:label "has coupon type" ; rdfs:domain fis:Bond ; rdfs:range xsd:string ;
    rdfs:comment "Takes value 'fixed', 'floating', 'zero' or 'inflationIndexed'." .

fis:FixedRateBond a owl:Class ; rdfs:subClassOf fis:Bond ;
    rdfs:label "fixed rate bond" ;
    rdfs:comment "Coupon remains constant throughout the life of the bond." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond [ a owl:Restriction ; owl:onProperty fis:hasCouponType ; owl:hasValue "fixed" ] ) ] .

fis:FloatingRateNote a owl:Class ; rdfs:subClassOf fis:Bond ;
    rdfs:label "floating rate note" ;
    rdfs:comment "Coupon varies, linked to a reference rate of interest such as LIBOR/SOFR or Euribor." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond [ a owl:Restriction ; owl:onProperty fis:hasCouponType ; owl:hasValue "floating" ] ) ] .

fis:ZeroCouponBond a owl:Class ; rdfs:subClassOf fis:Bond ;
    rdfs:label "zero-coupon bond" , "discount bond" ;
    rdfs:comment "Pays no regular interest; issued at a substantial discount to par, with the holder receiving full face value at maturity." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond [ a owl:Restriction ; owl:onProperty fis:hasCouponType ; owl:hasValue "zero" ] ) ] .

fis:InflationIndexedBond a owl:Class ; rdfs:subClassOf fis:Bond ;
    rdfs:label "inflation-indexed bond" , "linker" , "index-linked bond" ;
    rdfs:comment "Principal amount and interest payments are indexed to the level of consumer prices." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond [ a owl:Restriction ; owl:onProperty fis:hasCouponType ; owl:hasValue "inflationIndexed" ] ) ] .

[] a owl:AllDisjointClasses ; owl:members ( fis:FixedRateBond fis:FloatingRateNote fis:ZeroCouponBond fis:InflationIndexedBond ) .

# --- Eurosecurities ---

fis:Eurobond a owl:Class ; rdfs:subClassOf fis:Bond ;
    rdfs:comment "A Euro debt security issued internationally outside the issuer's domestic market, in a different denomination; characteristically underwritten, unsecured, interest paid gross." .
fis:Euronote a owl:Class ; rdfs:subClassOf fis:DebtSecurity ;
    rdfs:comment "A Euro debt security issued internationally outside the issuer's domestic market, taking the form of euro-commercial paper or euro-certificates of deposit." .

#################################################################
# MONEY MARKET INSTRUMENTS
#################################################################

fis:MoneyMarketInstrument a owl:Class ;
    rdfs:subClassOf fis:DebtSecurity ;
    rdfs:label "money market instrument" ;
    rdfs:comment "Short-term debt instrument with an original maturity of one year or less, highly liquid, sometimes called 'near cash'." ;
    owl:equivalentClass [ a owl:Class ;
        owl:intersectionOf ( fis:DebtSecurity
            [ a owl:Restriction ; owl:onProperty fis:hasOriginalTermInDays ;
              owl:someValuesFrom [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
                  owl:withRestrictions ( [ xsd:maxInclusive 365 ] ) ] ]
        )
    ] .

fis:CommercialPaper a owl:Class ;
    rdfs:subClassOf fis:MoneyMarketInstrument ;
    rdfs:label "commercial paper" ;
    rdfs:comment "Unsecured promissory note with fixed maturity usually less than 270 days, sold at a discount and backed only by the issuer's promise to pay." ;
    owl:equivalentClass [ a owl:Class ;
        owl:intersectionOf ( fis:MoneyMarketInstrument
            [ a owl:Restriction ; owl:onProperty fis:hasOriginalTermInDays ;
              owl:someValuesFrom [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
                  owl:withRestrictions ( [ xsd:maxInclusive 270 ] ) ] ]
        )
    ] .

fis:TreasuryBill a owl:Class ;
    rdfs:subClassOf fis:MoneyMarketInstrument ;
    rdfs:label "treasury bill" ;
    rdfs:comment "Short-term debt obligation of a national government, maturing in three to twelve months, sold at a discount." ;
    owl:equivalentClass [ a owl:Class ;
        owl:intersectionOf ( fis:MoneyMarketInstrument
            [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SovereignGovernment ]
        )
    ] .

fis:CertificateOfDeposit a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument ;
    rdfs:label "certificate of deposit" ;
    rdfs:comment "A time deposit sold by banks, thrift institutions and credit unions, with a fixed term before withdrawal without penalty." .

fis:BankersAcceptance a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument ;
    rdfs:comment "A bill of exchange drawn on and accepted by a bank." .

fis:RepurchaseAgreement a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument ;
    rdfs:label "repurchase agreement" ;
    rdfs:comment "Short-term loan arranged by selling securities with an agreement to repurchase them at a fixed price on a fixed date." .

fis:MunicipalNote a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument ;
    rdfs:comment "Short-term note issued by a municipality in anticipation of tax receipts or other revenues." .

fis:EuroCommercialPaper a owl:Class ; rdfs:subClassOf fis:CommercialPaper, fis:Euronote .
fis:EuroCertificateOfDeposit a owl:Class ; rdfs:subClassOf fis:CertificateOfDeposit, fis:Euronote .

#################################################################
# ASSET-BACKED / MORTGAGE-BACKED SECURITIES
#################################################################

fis:AssetBackedSecurity a owl:Class ;
    rdfs:subClassOf fis:Bond ,
        [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:Asset ] ;
    rdfs:label "asset-backed security" ;
    rdfs:comment "A bond whose interest and principal payments are backed by underlying cash flows from a pool of other assets (loans, leases, receivables)." .

fis:MortgageBackedSecurity a owl:Class ;
    rdfs:subClassOf fis:AssetBackedSecurity ;
    rdfs:label "mortgage-backed security" ;
    rdfs:comment "An asset-backed security secured by a mortgage or collection of mortgages." ;
    owl:equivalentClass [ a owl:Class ;
        owl:intersectionOf ( fis:AssetBackedSecurity [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:Mortgage ] )
    ] .

fis:CollateralizedDebtObligation a owl:Class ;
    rdfs:subClassOf fis:AssetBackedSecurity ;
    rdfs:label "collateralized debt obligation" ;
    rdfs:comment "Structured asset-backed security backed by a pool of bonds or other debt obligations, sliced into tranches by seniority." ;
    owl:equivalentClass [ a owl:Class ;
        owl:intersectionOf ( fis:AssetBackedSecurity [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:DebtSecurity ] )
    ] .

fis:ResidentialMortgageBackedSecurity a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity ;
    rdfs:label "residential mortgage-backed security" ;
    rdfs:comment "Secured by single-family, one- to four-unit real estate." .
fis:CommercialMortgageBackedSecurity a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity ;
    rdfs:label "commercial mortgage-backed security" ;
    rdfs:comment "Secured by commercial and multi-family properties." .

[] a owl:AllDisjointClasses ; owl:members ( fis:ResidentialMortgageBackedSecurity fis:CommercialMortgageBackedSecurity ) .

fis:PassThroughSecurity a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity ;
    rdfs:comment "Interest and principal payments pass through from borrower to holder on a pro rata basis." .
fis:CollateralizedMortgageObligation a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity ;
    rdfs:label "collateralized mortgage obligation" , "pay-through bond" ;
    rdfs:comment "A debt obligation collateralized by the mortgage assets it owns, divided into tranches with different maturities and payment priorities." .
fis:StrippedMortgageBackedSecurity a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity ;
    rdfs:comment "Each mortgage payment's interest and principal components are separated into distinct securities." .
fis:InterestOnlyStrip a owl:Class ; rdfs:subClassOf fis:StrippedMortgageBackedSecurity ;
    rdfs:comment "A bond with cash flows backed by the interest component of mortgage payments." .
fis:PrincipalOnlyStrip a owl:Class ; rdfs:subClassOf fis:StrippedMortgageBackedSecurity ;
    rdfs:comment "A bond with cash flows backed by the principal repayment component of mortgage payments." .

[] a owl:AllDisjointClasses ; owl:members ( fis:InterestOnlyStrip fis:PrincipalOnlyStrip ) .

#################################################################
# EQUITY SECURITY / STOCK
#################################################################

fis:hasParValue a owl:DatatypeProperty ;
    rdfs:label "has par value" ; rdfs:domain fis:Stock ; rdfs:range xsd:decimal ;
    rdfs:comment "A nominal accounting value used to represent equity on the balance sheet; shares may also be issued without par value." .

fis:Stock a owl:Class ;
    rdfs:subClassOf fis:EquitySecurity ;
    rdfs:label "stock" , "share" , "equity" ;
    rdfs:comment "A unit by which ownership of a corporation or company is divided; a fractional part of ownership of the issuer." .

fis:hasStockCategory a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:label "has stock category" ; rdfs:domain fis:Stock ; rdfs:range xsd:string ;
    rdfs:comment "Takes value 'common' or 'preferred'." .

fis:CommonStock a owl:Class ;
    rdfs:subClassOf fis:Stock ;
    rdfs:label "common stock" , "ordinary share" , "voting share" ;
    rdfs:comment "Carries voting rights and the right to residual profits/liquidation proceeds after preferred stockholders and creditors are paid." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Stock [ a owl:Restriction ; owl:onProperty fis:hasStockCategory ; owl:hasValue "common" ] ) ] .

fis:PreferredStock a owl:Class ;
    rdfs:subClassOf fis:Stock, fis:HybridSecurity ;
    rdfs:label "preferred stock" , "preference share" ;
    rdfs:comment "A hybrid component of share capital, typically without voting rights, entitled to a fixed dividend before common stock and senior to common stock on liquidation, but subordinate to bonds." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Stock [ a owl:Restriction ; owl:onProperty fis:hasStockCategory ; owl:hasValue "preferred" ] ) ] .

[] a owl:AllDisjointClasses ; owl:members ( fis:CommonStock fis:PreferredStock ) .

fis:hasDividendRate a owl:DatatypeProperty ;
    rdfs:label "has dividend rate" ; rdfs:domain fis:PreferredStock ; rdfs:range xsd:decimal .

fis:hasDividendAccumulation a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:label "has dividend accumulation" ; rdfs:domain fis:PreferredStock ; rdfs:range xsd:string ;
    rdfs:comment "Takes value 'cumulative' or 'noncumulative'." .

fis:CumulativePreferredStock a owl:Class ; rdfs:subClassOf fis:PreferredStock ;
    rdfs:comment "Unpaid or reduced dividends accumulate and must be paid before any common dividend." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:PreferredStock [ a owl:Restriction ; owl:onProperty fis:hasDividendAccumulation ; owl:hasValue "cumulative" ] ) ] .

fis:NoncumulativePreferredStock a owl:Class ; rdfs:subClassOf fis:PreferredStock ;
    rdfs:label "noncumulative preferred stock" , "straight preferred stock" ;
    rdfs:comment "Passed dividends are lost rather than accumulated." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:PreferredStock [ a owl:Restriction ; owl:onProperty fis:hasDividendAccumulation ; owl:hasValue "noncumulative" ] ) ] .

[] a owl:AllDisjointClasses ; owl:members ( fis:CumulativePreferredStock fis:NoncumulativePreferredStock ) .

fis:RestrictedStock a owl:Class ; rdfs:subClassOf fis:Stock ;
    rdfs:label "restricted stock" , "Rule 144 stock" ;
    rdfs:comment "Stock acquired in unregistered form, subject to SEC Rule 144 restrictions on resale." .

# --- Depositary receipts ---

fis:DepositaryReceipt a owl:Class ;
    rdfs:subClassOf fis:EquitySecurity ;
    rdfs:label "depositary receipt" ;
    rdfs:comment "A negotiable financial instrument issued by a bank to represent a foreign company's publicly traded securities, trading on a local exchange." .

fis:AmericanDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt ;
    rdfs:label "American depositary receipt" ; rdfs:comment "Listed and traded in the United States." .
fis:EuropeanDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt ;
    rdfs:label "European depositary receipt" .
fis:GlobalDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt ;
    rdfs:label "global depositary receipt" .

[] a owl:AllDisjointClasses ; owl:members ( fis:AmericanDepositaryReceipt fis:EuropeanDepositaryReceipt fis:GlobalDepositaryReceipt ) .

#################################################################
# CONVERTIBLE / HYBRID SECURITIES
#################################################################

fis:hasConversionTarget a owl:ObjectProperty ;
    rdfs:label "has conversion target" ;
    rdfs:domain fis:ConvertibleSecurity ; rdfs:range fis:EquitySecurity ;
    rdfs:comment "The equity security into which a convertible security may be converted, or which a warrant holder may purchase." .

fis:ConvertibleSecurity a owl:Class ;
    rdfs:subClassOf fis:Security ;
    rdfs:label "convertible security" ;
    rdfs:comment "A security that can be converted, at the election of the holder (or, for mandatory convertibles, compulsorily), into the ordinary shares of the issuer or another company." .

fis:ConvertibleBond a owl:Class ;
    rdfs:subClassOf fis:Bond, fis:HybridSecurity, fis:ConvertibleSecurity ;
    rdfs:label "convertible bond" , "convertible note" , "convertible debenture" ;
    rdfs:comment "A bond that the holder can convert into a specified number of shares of the issuer's common stock or cash of equal value; a hybrid security with debt- and equity-like features. Also a compound financial instrument under IAS 32." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond [ a owl:Restriction ; owl:onProperty fis:hasConversionTarget ; owl:someValuesFrom fis:EquitySecurity ] ) ] .

fis:ExchangeableBond a owl:Class ;
    rdfs:subClassOf fis:ConvertibleBond ;
    rdfs:comment "Allows exchange into shares of a corporation other than the issuer." .

fis:MandatoryConvertibleBond a owl:Class ; rdfs:subClassOf fis:ConvertibleBond ;
    rdfs:comment "Forces the holder to convert into shares at maturity." .
fis:ContingentConvertibleBond a owl:Class ; rdfs:subClassOf fis:MandatoryConvertibleBond ;
    rdfs:label "contingent convertible bond" , "CoCo" ;
    rdfs:comment "Automatically converts into equity if a pre-specified trigger event occurs." .

fis:ConvertiblePreferredStock a owl:Class ;
    rdfs:subClassOf fis:PreferredStock, fis:ConvertibleSecurity ;
    rdfs:label "convertible preferred stock" , "convertible preference share" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:PreferredStock [ a owl:Restriction ; owl:onProperty fis:hasConversionTarget ; owl:someValuesFrom fis:CommonStock ] ) ] .

fis:hasStrikePrice a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:label "has strike price" ;
    rdfs:domain [ a owl:Class ; owl:unionOf ( fis:Option fis:Warrant ) ] ; rdfs:range xsd:decimal ;
    rdfs:comment "The fixed price at which the option or warrant holder may buy or sell the underlying." .

fis:hasExpirationDate a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:label "has expiration date" ;
    rdfs:domain [ a owl:Class ; owl:unionOf ( fis:Option fis:Warrant ) ] ; rdfs:range xsd:date .

fis:Warrant a owl:Class ;
    rdfs:subClassOf fis:HybridSecurity, fis:ConvertibleSecurity ;
    rdfs:label "warrant" , "equity warrant" ;
    rdfs:comment "An option issued by a company allowing the holder to purchase a specified number of shares at a specified price within a specified time; often issued with bonds or existing equities and may be separately tradeable." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:HybridSecurity [ a owl:Restriction ; owl:onProperty fis:hasConversionTarget ; owl:someValuesFrom fis:CommonStock ] ) ] .

#################################################################
# IAS 32 / IFRS 9 ACCOUNTING CLASSIFICATION
#################################################################

fis:FinancialAsset a owl:Class ;
    rdfs:label "financial asset" ;
    rdfs:comment "IAS 32: cash; an equity instrument of another entity; a contractual right to receive cash or another financial asset; or a contractual right to exchange financial instruments under potentially favourable conditions." .

fis:FinancialLiability a owl:Class ;
    rdfs:label "financial liability" ;
    rdfs:comment "IAS 32: a contractual obligation to deliver cash or another financial asset to another entity, or to exchange financial instruments under potentially unfavourable conditions. The substance-over-form test (not the instrument's legal name) determines whether an instrument is a financial liability or equity; e.g. a mandatorily redeemable preference share is a financial liability under IAS 32 even though commonly called preferred equity." .

fis:EquityInstrument a owl:Class ;
    rdfs:label "equity instrument" ;
    rdfs:comment "IAS 32: any contract that evidences a residual interest in the assets of an entity after deducting all of its liabilities. A contract settled in the issuer's own shares is equity only if it will be settled by delivering a fixed number of shares for a fixed amount of cash (the 'fixed-for-fixed' condition); otherwise it is a financial liability." .

fis:EquitySecurity rdfs:subClassOf fis:EquityInstrument .

fis:CompoundFinancialInstrument a owl:Class ;
    rdfs:subClassOf fis:FinancialInstrument ;
    rdfs:label "compound financial instrument" ;
    rdfs:comment "An instrument with both a financial-liability component and an equity component, which IAS 32 requires to be presented separately; e.g. a convertible bond." .

fis:ConvertibleBond rdfs:subClassOf fis:CompoundFinancialInstrument .

fis:hasLiabilityComponent a owl:ObjectProperty ;
    rdfs:label "has liability component" ;
    rdfs:domain fis:CompoundFinancialInstrument ; rdfs:range fis:FinancialLiability .

fis:hasEquityComponent a owl:ObjectProperty ;
    rdfs:label "has equity component" ;
    rdfs:domain fis:CompoundFinancialInstrument ; rdfs:range fis:EquityInstrument .

fis:hasMeasurementCategory a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:label "has measurement category" ;
    rdfs:domain fis:FinancialAsset ; rdfs:range xsd:string ;
    rdfs:comment "IFRS 9 measurement bucket: 'amortisedCost', 'FVOCI' or 'FVTPL', determined by the business model and the solely-payments-of-principal-and-interest (SPPI) contractual cash flow test." .

fis:AmortisedCostFinancialAsset a owl:Class ; rdfs:subClassOf fis:FinancialAsset ;
    rdfs:comment "Held to collect contractual cash flows; cash flows are solely payments of principal and interest." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:FinancialAsset [ a owl:Restriction ; owl:onProperty fis:hasMeasurementCategory ; owl:hasValue "amortisedCost" ] ) ] .

fis:FVOCIFinancialAsset a owl:Class ; rdfs:subClassOf fis:FinancialAsset ;
    rdfs:label "fair-value-through-OCI financial asset" ;
    rdfs:comment "Held both to collect contractual cash flows and to sell; passes the SPPI test." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:FinancialAsset [ a owl:Restriction ; owl:onProperty fis:hasMeasurementCategory ; owl:hasValue "FVOCI" ] ) ] .

fis:FVTPLFinancialAsset a owl:Class ; rdfs:subClassOf fis:FinancialAsset ;
    rdfs:label "fair-value-through-profit-or-loss financial asset" ;
    rdfs:comment "All other financial assets, including derivatives and equity investments without the FVOCI election." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:FinancialAsset [ a owl:Restriction ; owl:onProperty fis:hasMeasurementCategory ; owl:hasValue "FVTPL" ] ) ] .

[] a owl:AllDisjointClasses ; owl:members ( fis:AmortisedCostFinancialAsset fis:FVOCIFinancialAsset fis:FVTPLFinancialAsset ) .

#################################################################
# DERIVATIVES
#################################################################

fis:hasProductType a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:label "has product type" ; rdfs:domain fis:Derivative ; rdfs:range xsd:string ;
    rdfs:comment "Takes value 'lock' (obligates both parties for the contract term) or 'option' (gives the buyer a right but not an obligation)." .

fis:LockProduct a owl:Class ; rdfs:subClassOf fis:Derivative ;
    rdfs:label "lock product" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Derivative [ a owl:Restriction ; owl:onProperty fis:hasProductType ; owl:hasValue "lock" ] ) ] .

fis:OptionProduct a owl:Class ; rdfs:subClassOf fis:Derivative ;
    rdfs:label "option product" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Derivative [ a owl:Restriction ; owl:onProperty fis:hasProductType ; owl:hasValue "option" ] ) ] .

[] a owl:AllDisjointClasses ; owl:members ( fis:LockProduct fis:OptionProduct ) .

fis:hasOfferingVenueType a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:label "has offering venue type" ; rdfs:domain fis:Derivative ; rdfs:range xsd:string ;
    rdfs:comment "Takes value 'exchangeTraded' or 'overTheCounter'." .

fis:ExchangeTradedDerivative a owl:Class ; rdfs:subClassOf fis:Derivative, fis:OptionProduct ;
    rdfs:comment "Traded via specialized derivatives exchanges that guarantee performance and take initial margin." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Derivative [ a owl:Restriction ; owl:onProperty fis:hasOfferingVenueType ; owl:hasValue "exchangeTraded" ] ) ] .

fis:OverTheCounterDerivative a owl:Class ; rdfs:subClassOf fis:Derivative ;
    rdfs:comment "Privately traded and negotiated directly between two parties without an exchange or intermediary." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Derivative [ a owl:Restriction ; owl:onProperty fis:hasOfferingVenueType ; owl:hasValue "overTheCounter" ] ) ] .

[] a owl:AllDisjointClasses ; owl:members ( fis:ExchangeTradedDerivative fis:OverTheCounterDerivative ) .

# --- Underlying-type classification ---

fis:EquityDerivative a owl:Class ; rdfs:subClassOf fis:Derivative ; rdfs:label "equity derivative" .
fis:InterestRateDerivative a owl:Class ; rdfs:subClassOf fis:Derivative ; rdfs:label "interest rate derivative" .
fis:CurrencyDerivative a owl:Class ; rdfs:subClassOf fis:Derivative ; rdfs:label "currency derivative" , "foreign exchange derivative" .
fis:CommodityDerivative a owl:Class ; rdfs:subClassOf fis:Derivative ; rdfs:label "commodity derivative" .
fis:CreditDerivative a owl:Class ; rdfs:subClassOf fis:Derivative ;
    rdfs:label "credit derivative" ;
    rdfs:comment "A contract that transfers credit risk from a protection buyer to a protection seller." .

[] a owl:AllDisjointClasses ; owl:members ( fis:EquityDerivative fis:InterestRateDerivative fis:CurrencyDerivative fis:CommodityDerivative fis:CreditDerivative ) .

fis:StockDerivative a owl:Class ;
    rdfs:subClassOf fis:EquityDerivative ;
    rdfs:label "stock derivative" ;
    rdfs:comment "Any financial instrument for which the underlying asset is the price of an equity." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Derivative [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:EquitySecurity ] ) ] .

# --- Forward / Future ---

fis:Forward a owl:Class ;
    rdfs:subClassOf fis:LockProduct, fis:OverTheCounterDerivative ;
    rdfs:label "forward" , "forward contract" ;
    rdfs:comment "A non-standardized contract between two parties to buy or sell an asset at a specified future time at a price agreed today." .

fis:Future a owl:Class ;
    rdfs:subClassOf fis:LockProduct, fis:ExchangeTradedDerivative ;
    rdfs:label "future" , "futures contract" ;
    rdfs:comment "A standardized contract to buy or sell an asset of standardized quantity and quality for a price agreed today, with delivery and payment on a specified future (delivery) date, traded on a futures exchange with margining." .

fis:StockFuture a owl:Class ; rdfs:subClassOf fis:Future, fis:StockDerivative ;
    rdfs:comment "A cash-settled futures contract on the value of a stock or stock market index." .

# --- Option ---

fis:hasRightType a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:label "has right type" ; rdfs:domain fis:Option ; rdfs:range xsd:string ;
    rdfs:comment "Takes value 'call' or 'put'." .

fis:hasExerciseStyle a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:label "has exercise style" ; rdfs:domain fis:Option ; rdfs:range xsd:string ;
    rdfs:comment "Takes value 'american', 'european' or 'bermudan'." .

fis:Option a owl:Class ;
    rdfs:subClassOf fis:OptionProduct ;
    rdfs:label "option" ;
    rdfs:comment "A contract giving the buyer the right, but not the obligation, to buy or sell an underlying asset at a specified strike price on or before a specified expiration date; the seller has the corresponding obligation if exercised." .

fis:CallOption a owl:Class ; rdfs:subClassOf fis:Option ;
    rdfs:label "call option" ;
    rdfs:comment "The right, not the obligation, to buy the underlying at the strike price." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option [ a owl:Restriction ; owl:onProperty fis:hasRightType ; owl:hasValue "call" ] ) ] .

fis:PutOption a owl:Class ; rdfs:subClassOf fis:Option ;
    rdfs:label "put option" ;
    rdfs:comment "The right, not the obligation, to sell the underlying at the strike price." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option [ a owl:Restriction ; owl:onProperty fis:hasRightType ; owl:hasValue "put" ] ) ] .

[] a owl:AllDisjointClasses ; owl:members ( fis:CallOption fis:PutOption ) .

fis:AmericanOption a owl:Class ; rdfs:subClassOf fis:Option ;
    rdfs:comment "May be exercised on any trading day on or before expiration." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option [ a owl:Restriction ; owl:onProperty fis:hasExerciseStyle ; owl:hasValue "american" ] ) ] .

fis:EuropeanOption a owl:Class ; rdfs:subClassOf fis:Option ;
    rdfs:comment "May only be exercised on the expiry date." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option [ a owl:Restriction ; owl:onProperty fis:hasExerciseStyle ; owl:hasValue "european" ] ) ] .

fis:BermudanOption a owl:Class ; rdfs:subClassOf fis:Option ;
    rdfs:comment "May be exercised only on specified dates on or before expiration." ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option [ a owl:Restriction ; owl:onProperty fis:hasExerciseStyle ; owl:hasValue "bermudan" ] ) ] .

[] a owl:AllDisjointClasses ; owl:members ( fis:AmericanOption fis:EuropeanOption fis:BermudanOption ) .

fis:AsianOption a owl:Class ; rdfs:subClassOf fis:Option ;
    rdfs:comment "Payoff determined by the average underlying price over a preset time period." .
fis:BarrierOption a owl:Class ; rdfs:subClassOf fis:Option ;
    rdfs:comment "The underlying's price must pass a certain barrier level before the option can be exercised." .
fis:BinaryOption a owl:Class ; rdfs:subClassOf fis:Option ;
